-- ############################################################################
-- ## 2/17  20260928_fix_admin_profile_write_access.sql
-- ############################################################################
-- ============================================================================
-- Fix: Restore admin write-access to profiles (without reintroducing recursion)
-- ============================================================================
-- Bug: 20260918_fix_all_rls_policies.sql reset the profiles UPDATE policy to
-- a self-only check (auth.uid() = id) and dropped the old
-- profiles_update_admin_simple policy without replacing it. That left the
-- admin user-management screens (adminUpdateUser, adminDeactivateUser,
-- adminChangeUserRole in src/lib/services/admin.ts) with no RLS policy
-- allowing an admin to write to any profile row except their own — those
-- actions have been silently failing for any target user other than the
-- admin themselves.
--
-- Fix: add a second, additive UPDATE policy scoped to admins, using the
-- existing private.is_admin() SECURITY DEFINER helper. Postgres OR's
-- multiple permissive policies for the same command together, so this does
-- not touch or weaken the existing self-service policy — it only adds a
-- path for admins to update other users' rows. Because is_admin() is
-- SECURITY DEFINER and owned outside of the calling role, it does not
-- re-trigger the profiles RLS policies it's used inside of, so this cannot
-- reproduce the earlier infinite-recursion bug.
-- ============================================================================

DROP POLICY IF EXISTS profiles_admin_write_policy ON public.profiles;
CREATE POLICY profiles_admin_write_policy
ON public.profiles FOR UPDATE TO authenticated
USING ((SELECT private.is_admin()))
WITH CHECK ((SELECT private.is_admin()));

COMMENT ON POLICY profiles_admin_write_policy ON public.profiles IS
'Allows admins to update any profile (role changes, deactivation, edits). Additive to profiles_update_policy; uses the non-recursive private.is_admin() helper.';


-- ############################################################################
-- ## 3/17  20260929_documents_and_notifications.sql
-- ############################################################################
-- ============================================================================
-- Documents upload/download + Notifications
-- ============================================================================
-- Why this migration exists
--   * The live policy set for documents / storage.objects / notifications is
--     ambiguous: several ad-hoc SQL files define the same policies under
--     different names, and permissive policies are OR'd together. So this
--     migration DROPS every existing policy on those tables (by looking them up
--     in pg_policies) and recreates one clean, known set.
--   * 20260918 replaced the access-level-aware documents SELECT policy with one
--     that ignored access_level, letting a client read metadata of
--     "Lawyer Only" / "Confidential" documents. Restored here.
--   * 20260917 attached public.update_updated_at() to notifications, but that
--     table has no updated_at column, so every UPDATE (mark as read) errors.
--     Trigger removed here.
--   * Notifications could only be inserted for yourself, so a lawyer could never
--     notify a client. Notifications are now created by SECURITY DEFINER
--     triggers on documents / matters / appointments (cannot be forged from the
--     browser).
-- Safe to re-run.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Wipe existing policies on the tables we own here
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  pol RECORD;
BEGIN
  FOR pol IN
    SELECT policyname, schemaname, tablename
    FROM pg_policies
    WHERE (schemaname = 'public' AND tablename IN ('documents', 'notifications'))
       OR (schemaname = 'storage' AND tablename = 'objects'
           AND policyname LIKE 'documents\_storage\_%' ESCAPE '\')
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I.%I',
                   pol.policyname, pol.schemaname, pol.tablename);
  END LOOP;
END $$;

-- ----------------------------------------------------------------------------
-- 2. Helpers (SECURITY DEFINER so they are not blocked by matters/profiles RLS)
-- ----------------------------------------------------------------------------

-- Is the current user the client, the assigned lawyer, or an admin of this matter?
CREATE OR REPLACE FUNCTION private.user_can_access_matter(p_matter_id UUID)
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.matters AS m
    WHERE m.id = p_matter_id
      AND (
        m.client_id = (SELECT auth.uid())
        OR m.lawyer_id = (SELECT auth.uid())
        OR (SELECT private.is_admin())
      )
  );
$$;

-- Same check, but for a storage object name like '<matter_uuid>/<file>'.
-- Returns FALSE (instead of raising) when the first path segment is not a UUID.
CREATE OR REPLACE FUNCTION private.user_can_access_matter_path(p_name TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_first TEXT := split_part(p_name, '/', 1);
BEGIN
  IF v_first !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN FALSE;
  END IF;
  RETURN private.user_can_access_matter(v_first::UUID);
END;
$$;

-- Which access levels may this user assign when uploading to this matter?
--   client : only 'Client & Assigned Lawyer'  (never Public: Public = every
--            logged-in user, across all matters)
--   lawyer : 'Client & Assigned Lawyer', 'Staff Shared', 'Lawyer Only'
--   admin  : anything
CREATE OR REPLACE FUNCTION private.can_upload_document(
  p_matter_id UUID,
  p_access_level public.access_level
)
RETURNS BOOLEAN
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_role public.user_role;
BEGIN
  IF NOT private.user_can_access_matter(p_matter_id) THEN
    RETURN FALSE;
  END IF;

  v_role := private.get_user_role();

  RETURN CASE v_role
    WHEN 'admin'::public.user_role THEN TRUE
    WHEN 'lawyer'::public.user_role THEN p_access_level IN (
      'Client & Assigned Lawyer'::public.access_level,
      'Staff Shared'::public.access_level,
      'Lawyer Only'::public.access_level
    )
    WHEN 'client'::public.user_role THEN
      p_access_level = 'Client & Assigned Lawyer'::public.access_level
    ELSE FALSE
  END;
END;
$$;

-- Access-level rules (unchanged from schema-production.sql; re-declared here so
-- this migration does not depend on which base schema file was run).
CREATE OR REPLACE FUNCTION private.can_access_document(
  p_matter_id UUID,
  p_access_level public.access_level
)
RETURNS BOOLEAN
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := (SELECT auth.uid());
  v_role public.user_role;
  v_client_id UUID;
  v_lawyer_id UUID;
BEGIN
  SELECT p.role INTO v_role FROM public.profiles AS p WHERE p.id = v_user_id;

  SELECT m.client_id, m.lawyer_id INTO v_client_id, v_lawyer_id
  FROM public.matters AS m WHERE m.id = p_matter_id;

  RETURN CASE p_access_level
    WHEN 'Public'::public.access_level THEN TRUE
    WHEN 'Staff Shared'::public.access_level THEN v_role IN ('lawyer'::public.user_role, 'admin'::public.user_role)
    WHEN 'Client & Assigned Lawyer'::public.access_level THEN
      v_user_id IN (v_client_id, v_lawyer_id) OR v_role = 'admin'::public.user_role
    WHEN 'Lawyer Only'::public.access_level THEN
      v_user_id = v_lawyer_id OR v_role = 'admin'::public.user_role
    WHEN 'Confidential'::public.access_level THEN v_role = 'admin'::public.user_role
    ELSE FALSE
  END;
END;
$$;

REVOKE ALL ON FUNCTION private.can_access_document(UUID, public.access_level) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.can_access_document(UUID, public.access_level) TO authenticated;

REVOKE ALL ON FUNCTION private.user_can_access_matter(UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION private.user_can_access_matter_path(TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION private.can_upload_document(UUID, public.access_level) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.user_can_access_matter(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION private.user_can_access_matter_path(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION private.can_upload_document(UUID, public.access_level) TO authenticated;

-- ----------------------------------------------------------------------------
-- 3. documents table policies
-- ----------------------------------------------------------------------------
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;

-- Read: driven by can_access_document (defined in schema-production.sql),
-- the same function the storage policy uses, so metadata and file agree.
CREATE POLICY documents_select_by_access
ON public.documents FOR SELECT TO authenticated
USING ((SELECT private.can_access_document(matter_id, access_level)));

CREATE POLICY documents_insert_allowed
ON public.documents FOR INSERT TO authenticated
WITH CHECK (
  uploaded_by = (SELECT auth.uid())
  AND (SELECT private.can_upload_document(matter_id, access_level))
);

-- Uploader may edit their own row but not move it to another matter or
-- escalate the access level beyond what their role may set.
CREATE POLICY documents_update_own
ON public.documents FOR UPDATE TO authenticated
USING (uploaded_by = (SELECT auth.uid()))
WITH CHECK (
  uploaded_by = (SELECT auth.uid())
  AND (SELECT private.can_upload_document(matter_id, access_level))
);

CREATE POLICY documents_update_admin
ON public.documents FOR UPDATE TO authenticated
USING ((SELECT private.is_admin()))
WITH CHECK ((SELECT private.is_admin()));

CREATE POLICY documents_delete_own_or_admin
ON public.documents FOR DELETE TO authenticated
USING (uploaded_by = (SELECT auth.uid()) OR (SELECT private.is_admin()));

-- ----------------------------------------------------------------------------
-- 4. Storage bucket + policies
-- ----------------------------------------------------------------------------
-- Private bucket, 20 MB per file, common office/PDF/image types only.
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (
  'documents', 'documents', FALSE, 20971520,
  ARRAY[
    'application/pdf',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/vnd.ms-powerpoint',
    'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    'text/plain',
    'text/csv',
    'image/png',
    'image/jpeg',
    'image/webp'
  ]
)
ON CONFLICT (id) DO UPDATE
SET public = FALSE,
    file_size_limit = EXCLUDED.file_size_limit,
    allowed_mime_types = EXCLUDED.allowed_mime_types;

-- Upload: path must start with a matter id the user belongs to. The client
-- uploads the file first and inserts the documents row second.
CREATE POLICY documents_storage_insert
ON storage.objects FOR INSERT TO authenticated
WITH CHECK (
  bucket_id = 'documents'
  AND (SELECT private.user_can_access_matter_path(name))
);

-- Download: the object must have a documents row the user is allowed to read.
CREATE POLICY documents_storage_select
ON storage.objects FOR SELECT TO authenticated
USING (
  bucket_id = 'documents'
  AND (
    EXISTS (
      SELECT 1
      FROM public.documents AS d
      WHERE d.file_path = storage.objects.name
        AND private.can_access_document(d.matter_id, d.access_level)
    )
    -- The uploader must be able to see their own object between the storage
    -- upload and the documents insert (needed for upsert/rollback cleanup).
    OR (owner_id = (SELECT auth.uid())::TEXT)
  )
);

-- Delete: uploader or admin. The client deletes the object BEFORE the row.
CREATE POLICY documents_storage_delete
ON storage.objects FOR DELETE TO authenticated
USING (
  bucket_id = 'documents'
  AND (
    owner_id = (SELECT auth.uid())::TEXT
    OR (SELECT private.is_admin())
  )
);

-- ----------------------------------------------------------------------------
-- 5. notifications table
-- ----------------------------------------------------------------------------
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;

-- Broken trigger: notifications has no updated_at column.
DROP TRIGGER IF EXISTS notifications_updated_at ON public.notifications;

CREATE INDEX IF NOT EXISTS notifications_user_created_idx
  ON public.notifications (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS notifications_user_unread_idx
  ON public.notifications (user_id) WHERE read = FALSE;

-- Users read / update / delete only their own. There is deliberately NO insert
-- policy: rows are created by the SECURITY DEFINER triggers below.
CREATE POLICY notifications_select_own
ON public.notifications FOR SELECT TO authenticated
USING (user_id = (SELECT auth.uid()));

CREATE POLICY notifications_update_own
ON public.notifications FOR UPDATE TO authenticated
USING (user_id = (SELECT auth.uid()))
WITH CHECK (user_id = (SELECT auth.uid()));

CREATE POLICY notifications_delete_own
ON public.notifications FOR DELETE TO authenticated
USING (user_id = (SELECT auth.uid()));

-- Only the read state may be changed by the browser, not the content.
REVOKE UPDATE ON public.notifications FROM authenticated;
GRANT UPDATE (read, read_at) ON public.notifications TO authenticated;

-- Keep read_at consistent with read.
CREATE OR REPLACE FUNCTION private.notifications_set_read_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF NEW.read AND NOT OLD.read THEN
    NEW.read_at := COALESCE(NEW.read_at, NOW());
  ELSIF NOT NEW.read THEN
    NEW.read_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS notifications_set_read_at ON public.notifications;
CREATE TRIGGER notifications_set_read_at
BEFORE UPDATE ON public.notifications
FOR EACH ROW EXECUTE FUNCTION private.notifications_set_read_at();

-- Realtime: lets the portal bell update instantly. RLS still applies.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime')
     AND NOT EXISTS (
       SELECT 1 FROM pg_publication_tables
       WHERE pubname = 'supabase_realtime'
         AND schemaname = 'public' AND tablename = 'notifications'
     ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.notifications;
  END IF;
END $$;

-- ----------------------------------------------------------------------------
-- 6. Notification creation helper + triggers
-- ----------------------------------------------------------------------------
-- Not granted to any client role; only the triggers below call it.
CREATE OR REPLACE FUNCTION private.create_notification(
  p_user_id UUID,
  p_title TEXT,
  p_message TEXT,
  p_type TEXT DEFAULT 'info',
  p_link TEXT DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  -- Never notify the person who performed the action, or a null recipient.
  IF p_user_id IS NULL OR p_user_id IS NOT DISTINCT FROM (SELECT auth.uid()) THEN
    RETURN;
  END IF;

  INSERT INTO public.notifications (user_id, title, message, type, link)
  VALUES (p_user_id, p_title, p_message, p_type, p_link);
END;
$$;

REVOKE ALL ON FUNCTION private.create_notification(UUID, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC;

-- ---- documents: tell the people who are allowed to see the new file --------
CREATE OR REPLACE FUNCTION private.notify_document_uploaded()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_client UUID;
  v_lawyer UUID;
  v_number TEXT;
BEGIN
  SELECT m.client_id, m.lawyer_id, m.matter_number
  INTO v_client, v_lawyer, v_number
  FROM public.matters AS m
  WHERE m.id = NEW.matter_id;

  -- Recipients depend on who is allowed to open the document. 'Lawyer Only',
  -- 'Staff Shared' and 'Confidential' names are never sent to the client.
  IF NEW.access_level IN ('Client & Assigned Lawyer', 'Public') THEN
    PERFORM private.create_notification(
      v_client, 'New document on matter ' || v_number,
      'A document "' || NEW.name || '" was added to your matter.',
      'info', 'documents');
    PERFORM private.create_notification(
      v_lawyer, 'New document on matter ' || v_number,
      'A document "' || NEW.name || '" was added to matter ' || v_number || '.',
      'info', 'documents');
  ELSIF NEW.access_level IN ('Lawyer Only', 'Staff Shared') THEN
    PERFORM private.create_notification(
      v_lawyer, 'New document on matter ' || v_number,
      'A document "' || NEW.name || '" was added to matter ' || v_number || '.',
      'info', 'documents');
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS documents_notify_uploaded ON public.documents;
CREATE TRIGGER documents_notify_uploaded
AFTER INSERT ON public.documents
FOR EACH ROW EXECUTE FUNCTION private.notify_document_uploaded();

-- ---- matters: status change + lawyer assignment ----------------------------
CREATE OR REPLACE FUNCTION private.notify_matter_changed()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    PERFORM private.create_notification(
      NEW.client_id,
      'Matter ' || NEW.matter_number || ' is now ' || NEW.status::TEXT,
      'The status of your matter "' || NEW.title || '" was updated to ' || NEW.status::TEXT || '.',
      CASE WHEN NEW.status IN ('Active', 'Accepted', 'Resolved') THEN 'success' ELSE 'info' END,
      'matters');
  END IF;

  IF NEW.lawyer_id IS DISTINCT FROM OLD.lawyer_id AND NEW.lawyer_id IS NOT NULL THEN
    PERFORM private.create_notification(
      NEW.lawyer_id,
      'You were assigned matter ' || NEW.matter_number,
      'You are now the assigned lawyer for "' || NEW.title || '".',
      'info', 'matters');
    PERFORM private.create_notification(
      NEW.client_id,
      'A lawyer was assigned to matter ' || NEW.matter_number,
      'Your matter "' || NEW.title || '" now has an assigned lawyer.',
      'success', 'matters');
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS matters_notify_changed ON public.matters;
CREATE TRIGGER matters_notify_changed
AFTER UPDATE OF status, lawyer_id ON public.matters
FOR EACH ROW EXECUTE FUNCTION private.notify_matter_changed();

-- ---- appointments: new + status change -------------------------------------
CREATE OR REPLACE FUNCTION private.notify_appointment_changed()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_title TEXT;
  v_msg TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_title := 'New appointment scheduled';
    v_msg := NEW.appointment_type || ' on ' || NEW.date::TEXT || ' at ' || NEW.time || ' (' || NEW.mode::TEXT || ').';
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    v_title := 'Appointment ' || lower(NEW.status::TEXT);
    v_msg := NEW.appointment_type || ' on ' || NEW.date::TEXT || ' at ' || NEW.time || ' is now ' || NEW.status::TEXT || '.';
  ELSE
    RETURN NEW;
  END IF;

  PERFORM private.create_notification(NEW.client_id, v_title, v_msg,
    CASE WHEN NEW.status = 'Cancelled' THEN 'warning' ELSE 'info' END, 'appointments');
  PERFORM private.create_notification(NEW.lawyer_id, v_title, v_msg,
    CASE WHEN NEW.status = 'Cancelled' THEN 'warning' ELSE 'info' END, 'appointments');

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS appointments_notify_changed ON public.appointments;
CREATE TRIGGER appointments_notify_changed
AFTER INSERT OR UPDATE OF status ON public.appointments
FOR EACH ROW EXECUTE FUNCTION private.notify_appointment_changed();

-- ----------------------------------------------------------------------------
-- 7. Let lawyers/admins change a matter's status and assignment
-- ----------------------------------------------------------------------------
-- The portal's status dropdown never saved anywhere, so matter notifications
-- could never fire. Additive policies; existing matter policies are untouched.
DROP POLICY IF EXISTS matters_update_lawyer_status ON public.matters;
CREATE POLICY matters_update_lawyer_status
ON public.matters FOR UPDATE TO authenticated
USING (lawyer_id = (SELECT auth.uid()))
WITH CHECK (lawyer_id = (SELECT auth.uid()));

DROP POLICY IF EXISTS matters_update_admin ON public.matters;
CREATE POLICY matters_update_admin
ON public.matters FOR UPDATE TO authenticated
USING ((SELECT private.is_admin()))
WITH CHECK ((SELECT private.is_admin()));


-- ############################################################################
-- ## 4/17  20261001_consolidated_access_control.sql
-- ############################################################################
-- ============================================================================
-- 20261001  Consolidated access control, composite names, lawyer directory
-- ============================================================================
-- Run AFTER all earlier migrations. Safe to re-run.
-- Decisions implemented (from the owner):
--   * Confidential documents: option B. Admins see file name + metadata only.
--     Opening content needs a typed reason ("break-glass"), is audited and
--     notifies the assigned lawyer. Access = assigned lawyer + matter_members.
--   * Matters: clients are read-only. Assigned lawyer moves status along
--     allowed transitions. Admin creates matters, converts inquiries, reassigns.
--   * Composite names, birthday validation, audited profile edits.
--   * "Our Lawyers" served from a safe public view (fixes the 0-lawyers bug).
-- ============================================================================

CREATE SCHEMA IF NOT EXISTS private;

-- ----------------------------------------------------------------------------
-- 0. Audit helper (writes to the live audit_logs shape from 20260916)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION private.write_audit(
  p_event TEXT, p_desc TEXT, p_type TEXT, p_id TEXT,
  p_meta JSONB DEFAULT NULL, p_success BOOLEAN DEFAULT TRUE
) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $$
DECLARE v_uid UUID := auth.uid(); v_email TEXT; v_role TEXT;
BEGIN
  IF v_uid IS NULL THEN RETURN; END IF;  -- SQL editor / service role
  SELECT p.email, p.role::TEXT INTO v_email, v_role FROM public.profiles p WHERE p.id = v_uid;
  INSERT INTO public.audit_logs
    (user_id, user_email, user_role, event_type, event_description, resource_type, resource_id, metadata, success)
  VALUES (v_uid, v_email, v_role, p_event, p_desc, p_type, p_id, p_meta, p_success);
EXCEPTION WHEN OTHERS THEN
  -- Audit logging must never block the operation being audited (a profile edit,
  -- a matter update, ...). If audit_logs has drifted from the expected shape we
  -- warn loudly and let the caller continue.
  RAISE WARNING 'audit row skipped: %', SQLERRM;
END $$;
REVOKE ALL ON FUNCTION private.write_audit(TEXT,TEXT,TEXT,TEXT,JSONB,BOOLEAN) FROM PUBLIC;

-- ----------------------------------------------------------------------------
-- 1. Profiles: composite name, birthday, guarded + audited edits
-- ----------------------------------------------------------------------------
ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS honorific   TEXT,
  ADD COLUMN IF NOT EXISTS first_name  TEXT,
  ADD COLUMN IF NOT EXISTS middle_name TEXT,
  ADD COLUMN IF NOT EXISTS last_name   TEXT,
  ADD COLUMN IF NOT EXISTS suffix      TEXT,
  ADD COLUMN IF NOT EXISTS nickname    TEXT,
  ADD COLUMN IF NOT EXISTS is_active   BOOLEAN DEFAULT TRUE,
  ADD COLUMN IF NOT EXISTS deleted_at  TIMESTAMPTZ;

-- Backfill parts from legacy full_name (best effort; users can correct them in Profile)
UPDATE public.profiles p SET
  first_name  = t.parts[1],
  middle_name = CASE WHEN array_length(t.parts,1) > 2 THEN array_to_string(t.parts[2:array_length(t.parts,1)-1],' ') END,
  last_name   = CASE WHEN array_length(t.parts,1) > 1 THEN t.parts[array_length(t.parts,1)] END
FROM (
  SELECT id, string_to_array(btrim(regexp_replace(full_name,'^(Atty\.|Dr\.|Mr\.|Ms\.|Mrs\.)\s+','')),' ') AS parts
  FROM public.profiles WHERE first_name IS NULL AND full_name IS NOT NULL AND role = 'client'
) t
WHERE p.id = t.id AND array_length(t.parts,1) >= 1;

-- Keep full_name in sync so every existing screen keeps working.
CREATE OR REPLACE FUNCTION private.compose_full_name() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF NULLIF(btrim(NEW.first_name),'') IS NOT NULL AND NULLIF(btrim(NEW.last_name),'') IS NOT NULL THEN
    NEW.full_name := btrim(concat_ws(' ',
      NULLIF(btrim(NEW.honorific),''),
      btrim(NEW.first_name),
      CASE WHEN NULLIF(btrim(NEW.nickname),'') IS NOT NULL THEN '"' || btrim(NEW.nickname) || '"' END,
      NULLIF(btrim(NEW.middle_name),''),
      btrim(NEW.last_name)))
      || CASE WHEN NULLIF(btrim(NEW.suffix),'') IS NOT NULL THEN ', ' || btrim(NEW.suffix) ELSE '' END;
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS profiles_compose_name ON public.profiles;
CREATE TRIGGER profiles_compose_name BEFORE INSERT OR UPDATE ON public.profiles
FOR EACH ROW EXECUTE FUNCTION private.compose_full_name();

-- Who may change what on a profile
CREATE OR REPLACE FUNCTION private.guard_profile_update() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF NEW.date_of_birth IS NOT NULL AND (NEW.date_of_birth > CURRENT_DATE OR NEW.date_of_birth < DATE '1900-01-01') THEN
    RAISE EXCEPTION 'Birthday must be a real past date';
  END IF;
  IF auth.uid() IS NULL OR private.is_admin() THEN RETURN NEW; END IF;
  IF NEW.role IS DISTINCT FROM OLD.role
     OR NEW.email IS DISTINCT FROM OLD.email
     OR NEW.is_active IS DISTINCT FROM OLD.is_active
     OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
     OR NEW.position IS DISTINCT FROM OLD.position
     OR NEW.display_order IS DISTINCT FROM OLD.display_order THEN
    RAISE EXCEPTION 'You cannot change role, email, status, position or display order. Contact the firm.';
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS profiles_guard_update ON public.profiles;
CREATE TRIGGER profiles_guard_update BEFORE UPDATE ON public.profiles
FOR EACH ROW EXECUTE FUNCTION private.guard_profile_update();

-- Every profile change is audited with old/new values
CREATE OR REPLACE FUNCTION private.audit_profile_update() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_old JSONB := to_jsonb(OLD); v_new JSONB := to_jsonb(NEW); k TEXT; v_changes JSONB := '{}'::JSONB;
BEGIN
  FOR k IN SELECT jsonb_object_keys(v_new) LOOP
    IF k NOT IN ('updated_at','full_name') AND v_new->k IS DISTINCT FROM v_old->k THEN
      v_changes := v_changes || jsonb_build_object(k, jsonb_build_object('old', v_old->k, 'new', v_new->k));
    END IF;
  END LOOP;
  IF v_changes <> '{}'::JSONB THEN
    PERFORM private.write_audit(
      CASE WHEN auth.uid() = NEW.id THEN 'PROFILE_UPDATED' ELSE 'PROFILE_UPDATED_BY_ADMIN' END,
      'Profile fields changed: ' || (SELECT string_agg(key, ', ') FROM jsonb_object_keys(v_changes) key),
      'profile', NEW.id::TEXT, v_changes);
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS profiles_audit_update ON public.profiles;
CREATE TRIGGER profiles_audit_update AFTER UPDATE ON public.profiles
FOR EACH ROW EXECUTE FUNCTION private.audit_profile_update();

-- New-user trigger: read name parts, birthday, address, city from signup metadata
CREATE OR REPLACE FUNCTION private.handle_new_user() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE m JSONB := COALESCE(NEW.raw_user_meta_data,'{}'::JSONB); v_name TEXT;
BEGIN
  v_name := COALESCE(NULLIF(m->>'full_name',''), NULLIF(m->>'name',''),
    NULLIF(btrim(concat_ws(' ', m->>'first_name', m->>'middle_name', m->>'last_name')),''),
    split_part(COALESCE(NEW.email,''),'@',1), 'New User');
  INSERT INTO public.profiles
    (id, email, full_name, first_name, middle_name, last_name, suffix, phone, address, city, date_of_birth, role)
  VALUES (NEW.id, NEW.email, v_name,
    NULLIF(m->>'first_name',''), NULLIF(m->>'middle_name',''), NULLIF(m->>'last_name',''), NULLIF(m->>'suffix',''),
    NULLIF(m->>'phone',''), NULLIF(m->>'address',''), NULLIF(m->>'city',''),
    NULLIF(m->>'date_of_birth','')::DATE, 'client'::public.user_role)
  ON CONFLICT (id) DO UPDATE SET email = EXCLUDED.email;
  RETURN NEW;
END $$;

-- The function is useless without the trigger, and the trigger was only ever
-- created by schema-production.sql — which is not the base of every project
-- (the live one included). Without it, EVERY auth user (signup, the
-- admin-create-user edge function, and the lawyer seed below) is created with
-- no profiles row: the portal then cannot load a profile, and the seed's
-- email lookup finds nothing and re-inserts an existing auth user.
-- Guarded, because creating a trigger on auth.users needs table ownership and
-- a missing trigger must not block the rest of this file.
DO $$ BEGIN
  DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
  CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION private.handle_new_user();
  RAISE NOTICE 'on_auth_user_created is installed on auth.users';
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Could not install on_auth_user_created on auth.users (%): every new account will have no profiles row until it is created from the dashboard.', SQLERRM;
END $$;

-- ----------------------------------------------------------------------------
-- 2. New tables: matter team, notes, timeline, break-glass grants
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.matter_members (
  matter_id  UUID NOT NULL REFERENCES public.matters(id) ON DELETE CASCADE,
  lawyer_id  UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  added_by   UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (matter_id, lawyer_id)
);

CREATE TABLE IF NOT EXISTS public.matter_notes (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  matter_id  UUID NOT NULL REFERENCES public.matters(id) ON DELETE CASCADE,
  author_id  UUID NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,
  body       TEXT NOT NULL CHECK (char_length(btrim(body)) BETWEEN 1 AND 5000),
  visibility TEXT NOT NULL DEFAULT 'internal' CHECK (visibility IN ('internal','client')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.matter_events (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  matter_id         UUID NOT NULL REFERENCES public.matters(id) ON DELETE CASCADE,
  event_type        TEXT NOT NULL,
  title             TEXT NOT NULL,
  detail            TEXT,
  actor_id          UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  visible_to_client BOOLEAN NOT NULL DEFAULT TRUE,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.confidential_access_grants (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  document_id UUID NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE,
  admin_id    UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  reason      TEXT NOT NULL CHECK (char_length(btrim(reason)) >= 15),
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at  TIMESTAMPTZ NOT NULL DEFAULT NOW() + INTERVAL '15 minutes'
);

CREATE INDEX IF NOT EXISTS idx_matter_members_lawyer ON public.matter_members(lawyer_id);
CREATE INDEX IF NOT EXISTS idx_matter_notes_matter   ON public.matter_notes(matter_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_matter_events_matter  ON public.matter_events(matter_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_grants_doc_admin      ON public.confidential_access_grants(document_id, admin_id, expires_at);

ALTER TABLE public.matter_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.matter_notes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.matter_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.confidential_access_grants ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.matter_members, public.matter_notes, public.matter_events, public.confidential_access_grants FROM anon;

DROP TRIGGER IF EXISTS matter_notes_updated_at ON public.matter_notes;
CREATE TRIGGER matter_notes_updated_at BEFORE UPDATE ON public.matter_notes
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();

-- ----------------------------------------------------------------------------
-- 3. Helpers (SECURITY DEFINER so they are not blocked by RLS)
-- ----------------------------------------------------------------------------
-- Lawyer team = assigned lawyer + explicitly added lawyers. NOT admins.
CREATE OR REPLACE FUNCTION private.is_matter_lawyer_team(p_matter_id UUID) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (SELECT 1 FROM public.matters m WHERE m.id = p_matter_id AND m.lawyer_id = (SELECT auth.uid()))
      OR EXISTS (SELECT 1 FROM public.matter_members mm WHERE mm.matter_id = p_matter_id AND mm.lawyer_id = (SELECT auth.uid()));
$$;

-- Anyone connected to the matter: client, lawyer team, admin
CREATE OR REPLACE FUNCTION private.user_can_access_matter(p_matter_id UUID) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (SELECT 1 FROM public.matters m WHERE m.id = p_matter_id AND m.client_id = (SELECT auth.uid()))
      OR private.is_matter_lawyer_team(p_matter_id)
      OR (SELECT private.is_admin());
$$;

CREATE OR REPLACE FUNCTION private.matter_transition_allowed(
  p_old public.matter_status, p_new public.matter_status, p_is_admin BOOLEAN
) RETURNS BOOLEAN LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
  SELECT p_old = p_new OR CASE p_old
    WHEN 'New Inquiry'   THEN p_new IN ('Under Review','Closed')
    WHEN 'Under Review'  THEN p_new IN ('Consultation','Conflict Check','Closed')
    WHEN 'Consultation'  THEN p_new IN ('Conflict Check','Closed')
    WHEN 'Conflict Check' THEN p_new IN ('Accepted','Closed')   -- Accepted only after a conflict check
    WHEN 'Accepted'      THEN p_new IN ('Active','Closed')
    WHEN 'Active'        THEN p_new IN ('Resolved','Closed')
    WHEN 'Resolved'      THEN p_new IN ('Active','Closed')
    WHEN 'Closed'        THEN p_is_admin AND p_new = 'Under Review'
    ELSE FALSE END;
$$;

-- Metadata visibility of a document (file name, type, size, dates).
-- Admin sees metadata of everything; CONTENT is decided by can_read_document_content.
CREATE OR REPLACE FUNCTION private.can_access_document(p_matter_id UUID, p_access_level public.access_level)
RETURNS BOOLEAN LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_uid UUID := (SELECT auth.uid()); v_role public.user_role; v_client UUID;
BEGIN
  SELECT p.role INTO v_role FROM public.profiles p WHERE p.id = v_uid;
  SELECT m.client_id INTO v_client FROM public.matters m WHERE m.id = p_matter_id;
  RETURN CASE p_access_level
    WHEN 'Public'       THEN TRUE
    WHEN 'Staff Shared' THEN v_role IN ('lawyer','admin')
    WHEN 'Client & Assigned Lawyer' THEN v_uid = v_client OR private.is_matter_lawyer_team(p_matter_id) OR v_role = 'admin'
    WHEN 'Lawyer Only'  THEN private.is_matter_lawyer_team(p_matter_id) OR v_role = 'admin'
    WHEN 'Confidential' THEN private.is_matter_lawyer_team(p_matter_id) OR v_role = 'admin'  -- admin: metadata only
    ELSE FALSE END;
END $$;

-- Content access (storage). Confidential: lawyer team, or an admin with a live break-glass grant.
CREATE OR REPLACE FUNCTION private.can_read_document_content(p_document_id UUID) RETURNS BOOLEAN
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE d RECORD; v_uid UUID := (SELECT auth.uid());
BEGIN
  SELECT matter_id, access_level INTO d FROM public.documents WHERE id = p_document_id;
  IF NOT FOUND THEN RETURN FALSE; END IF;
  IF d.access_level = 'Confidential' THEN
    RETURN private.is_matter_lawyer_team(d.matter_id)
        OR EXISTS (SELECT 1 FROM public.confidential_access_grants g
                   WHERE g.document_id = p_document_id AND g.admin_id = v_uid AND g.expires_at > NOW());
  END IF;
  RETURN private.can_access_document(d.matter_id, d.access_level);
END $$;

CREATE OR REPLACE FUNCTION private.can_upload_document(p_matter_id UUID, p_access_level public.access_level)
RETURNS BOOLEAN LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF NOT private.user_can_access_matter(p_matter_id) THEN RETURN FALSE; END IF;
  RETURN CASE private.get_user_role()
    WHEN 'admin'  THEN p_access_level <> 'Confidential'      -- admins never author privileged content
    WHEN 'lawyer' THEN private.is_matter_lawyer_team(p_matter_id)
                       AND p_access_level IN ('Client & Assigned Lawyer','Staff Shared','Lawyer Only','Confidential')
    WHEN 'client' THEN p_access_level = 'Client & Assigned Lawyer'
    ELSE FALSE END;
END $$;

REVOKE ALL ON FUNCTION private.is_matter_lawyer_team(UUID), private.user_can_access_matter(UUID),
  private.matter_transition_allowed(public.matter_status, public.matter_status, BOOLEAN),
  private.can_access_document(UUID, public.access_level), private.can_read_document_content(UUID),
  private.can_upload_document(UUID, public.access_level) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.is_matter_lawyer_team(UUID), private.user_can_access_matter(UUID),
  private.matter_transition_allowed(public.matter_status, public.matter_status, BOOLEAN),
  private.can_access_document(UUID, public.access_level), private.can_read_document_content(UUID),
  private.can_upload_document(UUID, public.access_level) TO authenticated;

-- ----------------------------------------------------------------------------
-- 4. Matters: clients read-only; lawyer moves status; admin creates/reassigns
-- ----------------------------------------------------------------------------
DO $$ DECLARE pol RECORD; BEGIN
  FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename='matters' LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.matters', pol.policyname);
  END LOOP;
END $$;

DROP POLICY IF EXISTS matters_select_involved ON public.matters;
CREATE POLICY matters_select_involved ON public.matters FOR SELECT TO authenticated
  USING ((SELECT private.user_can_access_matter(id)));
DROP POLICY IF EXISTS matters_insert_admin ON public.matters;
CREATE POLICY matters_insert_admin ON public.matters FOR INSERT TO authenticated
  WITH CHECK ((SELECT private.is_admin()));
DROP POLICY IF EXISTS matters_update_admin ON public.matters;
CREATE POLICY matters_update_admin ON public.matters FOR UPDATE TO authenticated
  USING ((SELECT private.is_admin())) WITH CHECK ((SELECT private.is_admin()));
DROP POLICY IF EXISTS matters_update_assigned_lawyer ON public.matters;
CREATE POLICY matters_update_assigned_lawyer ON public.matters FOR UPDATE TO authenticated
  USING (lawyer_id = (SELECT auth.uid())) WITH CHECK (lawyer_id = (SELECT auth.uid()));
-- No client write policy and no DELETE policy: clients contact the firm by email/inquiry.

CREATE OR REPLACE FUNCTION private.guard_matter_update() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_admin BOOLEAN;
BEGIN
  IF auth.uid() IS NULL THEN RETURN NEW; END IF;
  v_admin := private.is_admin();
  IF NEW.client_id IS DISTINCT FROM OLD.client_id OR NEW.matter_number IS DISTINCT FROM OLD.matter_number THEN
    RAISE EXCEPTION 'Client and matter number cannot be changed';
  END IF;
  IF NOT v_admin AND (NEW.lawyer_id IS DISTINCT FROM OLD.lawyer_id OR NEW.practice_area IS DISTINCT FROM OLD.practice_area) THEN
    RAISE EXCEPTION 'Only an admin can reassign the lawyer or change the practice area';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT private.matter_transition_allowed(OLD.status, NEW.status, v_admin) THEN
      RAISE EXCEPTION 'Status cannot move from % to %', OLD.status, NEW.status;
    END IF;
    NEW.date_closed := CASE WHEN NEW.status = 'Closed' THEN CURRENT_DATE ELSE NULL END;
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS matters_guard_update ON public.matters;
CREATE TRIGGER matters_guard_update BEFORE UPDATE ON public.matters
FOR EACH ROW EXECUTE FUNCTION private.guard_matter_update();

-- Timeline + audit for matter changes
CREATE OR REPLACE FUNCTION private.log_matter_change() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.matter_events(matter_id,event_type,title,actor_id)
    VALUES (NEW.id,'created','Matter opened: ' || NEW.title, auth.uid());
  ELSE
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      INSERT INTO public.matter_events(matter_id,event_type,title,detail,actor_id)
      VALUES (NEW.id,'status','Status changed', OLD.status::TEXT || ' → ' || NEW.status::TEXT, auth.uid());
      PERFORM private.write_audit('MATTER_STATUS_CHANGED','Matter status ' || OLD.status || ' → ' || NEW.status,'matter',NEW.id::TEXT,
        jsonb_build_object('old',OLD.status,'new',NEW.status));
    END IF;
    IF NEW.lawyer_id IS DISTINCT FROM OLD.lawyer_id THEN
      INSERT INTO public.matter_events(matter_id,event_type,title,actor_id)
      VALUES (NEW.id,'assignment','Assigned lawyer changed', auth.uid());
      PERFORM private.write_audit('MATTER_LAWYER_REASSIGNED','Assigned lawyer changed','matter',NEW.id::TEXT,
        jsonb_build_object('old',OLD.lawyer_id,'new',NEW.lawyer_id));
    END IF;
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS matters_log_change ON public.matters;
CREATE TRIGGER matters_log_change AFTER INSERT OR UPDATE OF status, lawyer_id ON public.matters
FOR EACH ROW EXECUTE FUNCTION private.log_matter_change();

-- Team membership
DROP POLICY IF EXISTS matter_members_select ON public.matter_members;
CREATE POLICY matter_members_select ON public.matter_members FOR SELECT TO authenticated
  USING ((SELECT private.user_can_access_matter(matter_id)));
DROP POLICY IF EXISTS matter_members_insert ON public.matter_members;
CREATE POLICY matter_members_insert ON public.matter_members FOR INSERT TO authenticated
  WITH CHECK ((SELECT private.is_admin())
    OR EXISTS (SELECT 1 FROM public.matters m WHERE m.id = matter_members.matter_id AND m.lawyer_id = (SELECT auth.uid())));
DROP POLICY IF EXISTS matter_members_delete ON public.matter_members;
CREATE POLICY matter_members_delete ON public.matter_members FOR DELETE TO authenticated
  USING ((SELECT private.is_admin())
    OR EXISTS (SELECT 1 FROM public.matters m WHERE m.id = matter_members.matter_id AND m.lawyer_id = (SELECT auth.uid())));

CREATE OR REPLACE FUNCTION private.on_matter_member_change() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE r public.matter_members; v_assigned UUID;
BEGIN
  r := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  SELECT lawyer_id INTO v_assigned FROM public.matters WHERE id = r.matter_id;
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = r.lawyer_id AND role = 'lawyer') THEN
      RAISE EXCEPTION 'Only lawyers can be added to a matter team';
    END IF;
    NEW.added_by := auth.uid();
  END IF;
  PERFORM private.write_audit('MATTER_TEAM_' || TG_OP, 'Matter team member ' || lower(TG_OP), 'matter', r.matter_id::TEXT,
    jsonb_build_object('lawyer_id', r.lawyer_id));
  IF v_assigned IS NOT NULL AND v_assigned IS DISTINCT FROM auth.uid() THEN
    PERFORM private.create_notification(v_assigned, 'Matter team changed',
      'A lawyer was ' || CASE WHEN TG_OP='INSERT' THEN 'added to' ELSE 'removed from' END || ' one of your matters.', 'info', 'matters');
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;

DROP TRIGGER IF EXISTS matter_members_change_ins ON public.matter_members;
CREATE TRIGGER matter_members_change_ins BEFORE INSERT ON public.matter_members
FOR EACH ROW EXECUTE FUNCTION private.on_matter_member_change();
DROP TRIGGER IF EXISTS matter_members_change_del ON public.matter_members;
CREATE TRIGGER matter_members_change_del AFTER DELETE ON public.matter_members
FOR EACH ROW EXECUTE FUNCTION private.on_matter_member_change();

-- Notes: internal notes are for the lawyer team only (admins never see them)
DROP POLICY IF EXISTS matter_notes_select ON public.matter_notes;
CREATE POLICY matter_notes_select ON public.matter_notes FOR SELECT TO authenticated
  USING ((SELECT private.is_matter_lawyer_team(matter_id))
      OR (visibility = 'client' AND (SELECT private.user_can_access_matter(matter_id))));
DROP POLICY IF EXISTS matter_notes_insert ON public.matter_notes;
CREATE POLICY matter_notes_insert ON public.matter_notes FOR INSERT TO authenticated
  WITH CHECK (author_id = (SELECT auth.uid())
    AND ((SELECT private.is_matter_lawyer_team(matter_id))
      OR (visibility = 'client' AND (SELECT private.is_admin()))));
DROP POLICY IF EXISTS matter_notes_update_own ON public.matter_notes;
CREATE POLICY matter_notes_update_own ON public.matter_notes FOR UPDATE TO authenticated
  USING (author_id = (SELECT auth.uid())) WITH CHECK (author_id = (SELECT auth.uid()));
DROP POLICY IF EXISTS matter_notes_delete_own ON public.matter_notes;
CREATE POLICY matter_notes_delete_own ON public.matter_notes FOR DELETE TO authenticated
  USING (author_id = (SELECT auth.uid()));

CREATE OR REPLACE FUNCTION private.on_matter_note_insert() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_client UUID;
BEGIN
  INSERT INTO public.matter_events(matter_id,event_type,title,actor_id,visible_to_client)
  VALUES (NEW.matter_id,'note', CASE WHEN NEW.visibility='client' THEN 'Update from your lawyer' ELSE 'Internal note added' END,
          NEW.author_id, NEW.visibility = 'client');
  IF NEW.visibility = 'client' THEN
    SELECT client_id INTO v_client FROM public.matters WHERE id = NEW.matter_id;
    PERFORM private.create_notification(v_client, 'New update on your matter', left(NEW.body, 140), 'info', 'matters');
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS matter_notes_after_insert ON public.matter_notes;
CREATE TRIGGER matter_notes_after_insert AFTER INSERT ON public.matter_notes
FOR EACH ROW EXECUTE FUNCTION private.on_matter_note_insert();

-- Timeline: clients see client-visible events; staff see all
DROP POLICY IF EXISTS matter_events_select ON public.matter_events;
CREATE POLICY matter_events_select ON public.matter_events FOR SELECT TO authenticated
  USING ((visible_to_client AND (SELECT private.user_can_access_matter(matter_id)))
      OR (SELECT private.is_matter_lawyer_team(matter_id)) OR (SELECT private.is_admin()));
-- no INSERT/UPDATE/DELETE policy: rows are written by SECURITY DEFINER triggers only

-- ----------------------------------------------------------------------------
-- 5. Documents + storage (Confidential, option B)
-- ----------------------------------------------------------------------------
DROP POLICY IF EXISTS documents_select_by_access ON public.documents;
DROP POLICY IF EXISTS documents_select_by_access ON public.documents;
CREATE POLICY documents_select_by_access ON public.documents FOR SELECT TO authenticated
  USING ((SELECT private.can_access_document(matter_id, access_level)));

-- An admin must not be able to downgrade or delete a Confidential document
CREATE OR REPLACE FUNCTION private.guard_confidential_document() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF auth.uid() IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  IF OLD.access_level = 'Confidential' AND NOT private.is_matter_lawyer_team(OLD.matter_id) THEN
    RAISE EXCEPTION 'Only the matter''s lawyer team can change or delete a Confidential document';
  END IF;
  RETURN COALESCE(NEW, OLD);
END $$;
DROP TRIGGER IF EXISTS documents_guard_confidential ON public.documents;
CREATE TRIGGER documents_guard_confidential BEFORE UPDATE OR DELETE ON public.documents
FOR EACH ROW EXECUTE FUNCTION private.guard_confidential_document();

DROP POLICY IF EXISTS documents_storage_select ON storage.objects;
DROP POLICY IF EXISTS documents_storage_select ON storage.objects;
CREATE POLICY documents_storage_select ON storage.objects FOR SELECT TO authenticated
USING (
  bucket_id = 'documents'
  AND (
    EXISTS (SELECT 1 FROM public.documents d
            WHERE d.file_path = storage.objects.name AND private.can_read_document_content(d.id))
    OR owner_id = (SELECT auth.uid())::TEXT
  )
);

-- Break-glass: admin opens a Confidential file with a typed reason
CREATE OR REPLACE FUNCTION public.break_glass_open_document(p_document_id UUID, p_reason TEXT)
RETURNS TEXT LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE d RECORD;
BEGIN
  IF NOT private.is_admin() THEN RAISE EXCEPTION 'Admins only'; END IF;
  IF char_length(btrim(COALESCE(p_reason,''))) < 15 THEN
    RAISE EXCEPTION 'Please type a reason of at least 15 characters';
  END IF;
  SELECT doc.id, doc.name, doc.file_path, doc.matter_id, doc.access_level, m.lawyer_id, m.matter_number
    INTO d FROM public.documents doc JOIN public.matters m ON m.id = doc.matter_id WHERE doc.id = p_document_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Document not found'; END IF;
  IF d.access_level <> 'Confidential' THEN RAISE EXCEPTION 'Not a Confidential document; open it normally'; END IF;

  INSERT INTO public.confidential_access_grants(document_id, admin_id, reason)
  VALUES (p_document_id, auth.uid(), btrim(p_reason));

  PERFORM private.write_audit('CONFIDENTIAL_BREAK_GLASS','Admin opened a Confidential document','document', p_document_id::TEXT,
    jsonb_build_object('reason', btrim(p_reason), 'matter_id', d.matter_id, 'file', d.name));
  INSERT INTO public.matter_events(matter_id,event_type,title,detail,actor_id,visible_to_client)
  VALUES (d.matter_id,'break_glass','Confidential document opened by admin', btrim(p_reason), auth.uid(), FALSE);
  IF d.lawyer_id IS NOT NULL THEN
    PERFORM private.create_notification(d.lawyer_id, 'Confidential document opened by an admin',
      '"' || d.name || '" on ' || d.matter_number || ' was opened. Reason: ' || btrim(p_reason), 'warning', 'documents');
  END IF;
  RETURN d.file_path;
END $$;
REVOKE ALL ON FUNCTION public.break_glass_open_document(UUID, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.break_glass_open_document(UUID, TEXT) TO authenticated;

DROP POLICY IF EXISTS grants_select ON public.confidential_access_grants;
CREATE POLICY grants_select ON public.confidential_access_grants FOR SELECT TO authenticated
  USING (admin_id = (SELECT auth.uid())
      OR EXISTS (SELECT 1 FROM public.documents d WHERE d.id = document_id AND (SELECT private.is_matter_lawyer_team(d.matter_id))));

-- ----------------------------------------------------------------------------
-- 6. Appointments: client requests, lawyer/admin confirms
-- ----------------------------------------------------------------------------
DO $$ DECLARE pol RECORD; BEGIN
  FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename='appointments' LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.appointments', pol.policyname);
  END LOOP;
END $$;

DROP POLICY IF EXISTS appointments_select ON public.appointments;
CREATE POLICY appointments_select ON public.appointments FOR SELECT TO authenticated
  USING ((SELECT auth.uid()) IN (client_id, lawyer_id) OR (SELECT private.is_admin()));
DROP POLICY IF EXISTS appointments_insert ON public.appointments;
CREATE POLICY appointments_insert ON public.appointments FOR INSERT TO authenticated
WITH CHECK (
  (SELECT private.is_admin())
  OR (client_id = (SELECT auth.uid()) AND status = 'Pending'
      AND EXISTS (SELECT 1 FROM public.matters m WHERE m.id = appointments.matter_id AND m.client_id = (SELECT auth.uid()) AND m.lawyer_id = appointments.lawyer_id))
  OR (lawyer_id = (SELECT auth.uid())
      AND EXISTS (SELECT 1 FROM public.matters m WHERE m.id = appointments.matter_id AND m.lawyer_id = (SELECT auth.uid()) AND m.client_id = appointments.client_id))
);
DROP POLICY IF EXISTS appointments_update ON public.appointments;
CREATE POLICY appointments_update ON public.appointments FOR UPDATE TO authenticated
  USING ((SELECT auth.uid()) IN (client_id, lawyer_id) OR (SELECT private.is_admin()))
  WITH CHECK ((SELECT auth.uid()) IN (client_id, lawyer_id) OR (SELECT private.is_admin()));

CREATE OR REPLACE FUNCTION private.guard_appointment_update() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF auth.uid() IS NULL OR private.is_admin() THEN RETURN NEW; END IF;
  IF NEW.matter_id IS DISTINCT FROM OLD.matter_id OR NEW.client_id IS DISTINCT FROM OLD.client_id
     OR NEW.lawyer_id IS DISTINCT FROM OLD.lawyer_id THEN
    RAISE EXCEPTION 'Matter, client and lawyer of an appointment cannot be changed';
  END IF;
  IF auth.uid() = OLD.client_id AND auth.uid() <> OLD.lawyer_id THEN
    IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status <> 'Cancelled' THEN
      RAISE EXCEPTION 'Clients can only cancel an appointment; the firm confirms it';
    END IF;
    IF NEW.date IS DISTINCT FROM OLD.date OR NEW.time IS DISTINCT FROM OLD.time OR NEW.mode IS DISTINCT FROM OLD.mode THEN
      RAISE EXCEPTION 'To reschedule, cancel and request a new time';
    END IF;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS appointments_guard_update ON public.appointments;
CREATE TRIGGER appointments_guard_update BEFORE UPDATE ON public.appointments
FOR EACH ROW EXECUTE FUNCTION private.guard_appointment_update();

-- ----------------------------------------------------------------------------
-- 7. Inquiry -> matter (admin only, atomic)
-- ----------------------------------------------------------------------------
CREATE SEQUENCE IF NOT EXISTS public.matter_number_seq START 1;

CREATE OR REPLACE FUNCTION public.convert_inquiry_to_matter(
  p_inquiry_id UUID, p_lawyer_id UUID, p_title TEXT DEFAULT NULL,
  p_priority public.priority_level DEFAULT 'Medium'
) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE i public.inquiries; v_client UUID; v_num TEXT; v_id UUID;
BEGIN
  IF NOT private.is_admin() THEN RAISE EXCEPTION 'Admins only'; END IF;
  SELECT * INTO i FROM public.inquiries WHERE id = p_inquiry_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Inquiry not found'; END IF;
  IF i.status = 'Converted' THEN RAISE EXCEPTION 'Inquiry was already converted'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_lawyer_id AND role = 'lawyer' AND COALESCE(is_active,TRUE)) THEN
    RAISE EXCEPTION 'Selected user is not an active lawyer';
  END IF;
  v_client := i.client_id;
  IF v_client IS NULL THEN
    SELECT id INTO v_client FROM public.profiles WHERE lower(email) = lower(i.email) AND role = 'client';
  END IF;
  IF v_client IS NULL THEN
    RAISE EXCEPTION 'No client account for %. Ask the client to register with this email first.', i.email;
  END IF;
  LOOP
    v_num := 'WLF-' || to_char(NOW(),'YYYY') || '-' || lpad(nextval('public.matter_number_seq')::TEXT, 4, '0');
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.matters WHERE matter_number = v_num);
  END LOOP;
  INSERT INTO public.matters(matter_number, client_id, lawyer_id, practice_area, status, priority, title, description)
  VALUES (v_num, v_client, p_lawyer_id, i.practice_area, 'Under Review', p_priority,
          COALESCE(NULLIF(btrim(p_title),''), i.subject), i.message)
  RETURNING id INTO v_id;
  UPDATE public.inquiries SET status = 'Converted', client_id = v_client, assigned_to = p_lawyer_id WHERE id = p_inquiry_id;
  PERFORM private.write_audit('INQUIRY_CONVERTED','Inquiry converted to matter ' || v_num,'inquiry', p_inquiry_id::TEXT,
    jsonb_build_object('matter_id', v_id, 'lawyer_id', p_lawyer_id));
  RETURN v_id;
END $$;
REVOKE ALL ON FUNCTION public.convert_inquiry_to_matter(UUID,UUID,TEXT,public.priority_level) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.convert_inquiry_to_matter(UUID,UUID,TEXT,public.priority_level) TO authenticated;

-- ----------------------------------------------------------------------------
-- 8. Lawyer directory: real data, safe for the public site
-- ----------------------------------------------------------------------------
-- Root cause of "0 lawyers": visitors cannot read `profiles` (RLS) and the code
-- filtered on a column that did not exist on some databases, so the page fell
-- back to mock lawyers that had no practice areas. This view exposes ONLY
-- public-safe columns (work email as shown on the site; no phone, address or
-- birthday).
CREATE OR REPLACE VIEW public.public_lawyers AS
SELECT p.id, p.email, p.honorific, p.first_name, p.nickname, p.middle_name, p.last_name, p.suffix, p.full_name,
       p.position, p.bio, p.education, p.bar_admissions, p.experience_years, p.profile_image,
       p.linkedin_url, p.display_order, p.city,
       COALESCE((SELECT jsonb_agg(jsonb_build_object('id', pa.id, 'name', pa.name, 'slug', pa.slug, 'icon', pa.icon)
                                  ORDER BY pa.display_order)
                 FROM public.profile_practice_areas ppa
                 JOIN public.practice_areas pa ON pa.id = ppa.practice_area_id AND pa.is_active
                 WHERE ppa.profile_id = p.id), '[]'::JSONB) AS practice_areas
FROM public.profiles p
WHERE p.role = 'lawyer' AND COALESCE(p.is_active, TRUE) AND p.deleted_at IS NULL;
GRANT SELECT ON public.public_lawyers TO anon, authenticated;

ALTER TABLE public.practice_areas ADD COLUMN IF NOT EXISTS lawyer_ids TEXT[] NOT NULL DEFAULT '{}';

-- Seed the firm's lawyers (idempotent). Directory accounts are created without a
-- usable password; use "Forgot password" or the admin-create-user function to let
-- a lawyer sign in. Education/experience are left blank on purpose: enter the
-- verified details from the Profile screen rather than guessing them here.
DO $seed$
DECLARE r RECORD; v_uid UUID;
BEGIN
  FOR r IN SELECT * FROM (VALUES
  ('l1', 'atty.boyet@westwoodlaw.ph', 'Ernesto', 'Boyet', '', 'Tabao', 'Managing Partner', '/lawyers/atty-tabao-primary.png', 'Labor, industrial relations, corporate, and business law practitioner.', 1),
  ('l2', 'mc.santos@westwoodlaw.ph', 'Maria Cristina', '', 'L.', 'Santos', 'Senior Associate', 'https://images.unsplash.com/photo-1662104935883-e9dd0619eaba?w=400&h=500&fit=crop&auto=format', 'Civil and administrative matters practitioner with litigation experience.', 2),
  ('l3', 'bj.reyes@westwoodlaw.ph', 'Benjamin Jose', '', 'T.', 'Reyes', 'Associate', 'https://images.unsplash.com/photo-1560250097-0b93528c311a?w=400&h=500&fit=crop&auto=format', 'Corporate and commercial law practitioner focused on business matters.', 3),
  ('l4', 'l.delacruz@westwoodlaw.ph', 'Lorraine', '', 'A.', 'Dela Cruz', 'Associate', 'https://images.unsplash.com/photo-1614786269829-d24616faf56d?w=400&h=500&fit=crop&auto=format', 'Immigration practitioner handling visas and residency documentation.', 4),
  ('l5', 'cg.torres@westwoodlaw.ph', 'Carlos Gabriel', '', 'M.', 'Torres', 'Associate', 'https://images.unsplash.com/photo-1534030347209-467a5b0ad3e6?w=400&h=500&fit=crop&auto=format', 'Taxation and banking law practitioner advising businesses and families.', 5),
  ('l6', 'si.mendoza@westwoodlaw.ph', 'Sofia Isabelle', '', 'B.', 'Mendoza', 'Associate', 'https://images.unsplash.com/photo-1662104935762-707db0439ecd?w=400&h=500&fit=crop&auto=format', 'Family law practitioner focused on sensitive annulment matters.', 6),
  ('l7', 'ma.villanueva@westwoodlaw.ph', 'Marco Antonio', '', 'R.', 'Villanueva', 'Associate', 'https://images.unsplash.com/photo-1613496701765-97267d26e3df?w=400&h=500&fit=crop&auto=format', 'Energy, mining, cooperatives, and regulatory compliance practitioner.', 7)
  ) AS t(lid, email, first_name, nickname, middle_name, last_name, position, img, bio, ord)
  LOOP
    -- Find the account by email on BOTH sides. Matching profiles alone is not
    -- enough: an auth user can exist with no profile row (it was created before
    -- on_auth_user_created existed, or by a project whose base schema never had
    -- it). The seed would then try to insert that email again and die on
    -- auth.users' users_email_partial_key — which is exactly what happened on
    -- the live project.
    SELECT id INTO v_uid FROM public.profiles WHERE lower(email) = lower(r.email);
    IF v_uid IS NULL THEN
      SELECT id INTO v_uid FROM auth.users WHERE lower(email) = lower(r.email);
    END IF;

    IF v_uid IS NULL THEN
      v_uid := gen_random_uuid();
      INSERT INTO auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
                              raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
                              confirmation_token, email_change, email_change_token_new, recovery_token)
      VALUES ('00000000-0000-0000-0000-000000000000', v_uid, 'authenticated', 'authenticated', r.email,
              extensions.crypt(gen_random_uuid()::TEXT, extensions.gen_salt('bf')), NOW(),
              '{"provider":"email","providers":["email"]}'::JSONB,
              jsonb_build_object('first_name', r.first_name, 'last_name', r.last_name), NOW(), NOW(), '', '', '', '');
    END IF;

    -- Guarantee the profile row before the UPDATE below: an UPDATE against a
    -- missing row matches nothing, exits 0, and leaves the lawyer invisible in
    -- the directory while the migration reports success.
    INSERT INTO public.profiles (id, email, full_name, first_name, middle_name, last_name, role)
    VALUES (v_uid, r.email, btrim(concat_ws(' ', r.first_name, r.last_name)),
            r.first_name, NULLIF(r.middle_name,''), r.last_name, 'lawyer'::public.user_role)
    ON CONFLICT DO NOTHING;

    UPDATE public.profiles SET
      role = 'lawyer', honorific = 'Atty.', first_name = r.first_name, nickname = NULLIF(r.nickname,''),
      middle_name = NULLIF(r.middle_name,''), last_name = r.last_name, position = r.position,
      bio = r.bio, profile_image = r.img, display_order = r.ord, is_active = TRUE,
      city = COALESCE(city, 'San Juan City'),
      bar_admissions = CASE WHEN bar_admissions IS NULL OR bar_admissions = '[]'::JSONB
                            THEN '["Philippine Bar"]'::JSONB ELSE bar_admissions END
    WHERE id = v_uid;
    -- keep the practice-area link keyed by the old seed ids l1..l7
    INSERT INTO public.profile_practice_areas(profile_id, practice_area_id)
    SELECT v_uid, pa.id FROM public.practice_areas pa WHERE r.lid = ANY(pa.lawyer_ids)
    ON CONFLICT DO NOTHING;
  END LOOP;
END $seed$;

-- ----------------------------------------------------------------------------
-- 8b. Link seeded articles to their author's lawyer profile
-- ----------------------------------------------------------------------------
-- The content seed stores each byline as free text (articles.author_name). Now
-- that the lawyer profiles exist we can resolve the real author, so the article
-- pages show the linked lawyer instead of falling back to the firm name.
UPDATE public.articles a SET author_id = p.id
FROM public.profiles p
WHERE a.author_id IS NULL
  AND p.role = 'lawyer'
  AND a.author_name IS NOT NULL
  AND p.full_name = a.author_name;

-- ----------------------------------------------------------------------------
-- 9. Housekeeping notes (nothing destructive runs here)
-- ----------------------------------------------------------------------------
-- Guarded: 20261002 renames this table to lawyers_legacy, so on a re-run it is
-- no longer there.
DO $$
BEGIN
  IF to_regclass('public.lawyers') IS NOT NULL THEN
    COMMENT ON TABLE public.lawyers IS 'DEPRECATED: unused by the app. Lawyer data lives on profiles. See supabase/DATABASE_REVIEW.md';
  END IF;
END $$;

-- ----------------------------------------------------------------------------
-- 10. No double-booking of a lawyer's time slot
-- ----------------------------------------------------------------------------
DO $$ BEGIN
  CREATE UNIQUE INDEX IF NOT EXISTS uq_appointments_lawyer_slot
    ON public.appointments (lawyer_id, date, time) WHERE status IN ('Pending', 'Confirmed');
EXCEPTION WHEN unique_violation THEN
  RAISE NOTICE 'Existing appointments already overlap; resolve them, then re-run this statement to enforce the rule.';
END $$;


-- ############################################################################
-- ## 5/17  20261002_database_cleanup.sql
-- ############################################################################
-- ============================================================================
-- 20261002  Non-destructive cleanup + routing fixes
-- ============================================================================
-- Run AFTER 20261001_consolidated_access_control.sql. Safe to re-run.
--
-- This migration does NOT drop any table or data. It:
--   1. Renames legacy tables to *_legacy so they are clearly inactive but
--      remain as read-only backup until you are confident they can be removed.
--   2. Backfills profile_practice_areas from the old practice_areas.lawyer_ids
--      column so the "Our Lawyers" page shows the right lawyers per area.
--   3. Drops only the RLS policies on the renamed legacy tables (they no
--      longer need active policies). The tables themselves are kept.
--
-- Legacy tables (no screen in src/ reads them):
--   * lawyers           — lawyer data lives on profiles / public_lawyers view.
--   * saved_lawyers     — favourites use localStorage; FK pointed at lawyers.
--   * consultations     — duplicates inquiries + appointments; never written to.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Rename legacy tables (keep data, deactivate)
-- ----------------------------------------------------------------------------

-- Only rename if the original exists and the _legacy name is free.
DO $$
BEGIN
  IF to_regclass('public.lawyers') IS NOT NULL AND to_regclass('public.lawyers_legacy') IS NULL THEN
    ALTER TABLE public.lawyers RENAME TO lawyers_legacy;
    RAISE NOTICE 'Renamed public.lawyers → lawyers_legacy';
  END IF;

  IF to_regclass('public.saved_lawyers') IS NOT NULL AND to_regclass('public.saved_lawyers_legacy') IS NULL THEN
    ALTER TABLE public.saved_lawyers RENAME TO saved_lawyers_legacy;
    RAISE NOTICE 'Renamed public.saved_lawyers → saved_lawyers_legacy';
  END IF;

  IF to_regclass('public.consultations') IS NOT NULL AND to_regclass('public.consultations_legacy') IS NULL THEN
    ALTER TABLE public.consultations RENAME TO consultations_legacy;
    RAISE NOTICE 'Renamed public.consultations → consultations_legacy';
  END IF;
END $$;

-- Disable RLS on legacy tables so they stop interfering with policy audits.
ALTER TABLE IF EXISTS public.lawyers_legacy DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS public.saved_lawyers_legacy DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS public.consultations_legacy DISABLE ROW LEVEL SECURITY;

-- Drop any leftover policies on the renamed tables.
DO $$ DECLARE pol RECORD; BEGIN
  FOR pol IN
    SELECT policyname, tablename
    FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename IN ('lawyers_legacy','saved_lawyers_legacy','consultations_legacy')
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', pol.policyname, pol.tablename);
  END LOOP;
END $$;

-- ----------------------------------------------------------------------------
-- 2. Backfill profile_practice_areas from practice_areas.lawyer_ids
-- ----------------------------------------------------------------------------
-- The old practice_areas.lawyer_ids column holds seed ids ('l1','l2',...).
-- The 20261001 migration seeds lawyers with those same lids in the VALUES
-- block, so we can join on them to build the real profile_practice_areas rows.
-- This is idempotent (ON CONFLICT DO NOTHING).

DO $$
DECLARE
  pa RECORD;
  v_profile_id UUID;
  v_lid TEXT;
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'practice_areas' AND column_name = 'lawyer_ids'
  ) THEN
    FOR pa IN SELECT id, lawyer_ids FROM public.practice_areas WHERE lawyer_ids IS NOT NULL AND array_length(lawyer_ids, 1) > 0 LOOP
      FOREACH v_lid IN ARRAY pa.lawyer_ids LOOP
        -- The seed block in 20261001 keys lawyers by these lids in the VALUES list.
        -- We can't join on the lid directly (it's not a column), so we match by
        -- the order they were inserted: l1..l7 map to the seeded auth.users emails.
        -- Instead, use the public_lawyers view which is already populated.
        CONTINUE;  -- profile_practice_areas is already seeded by 20261001's DO $seed$ block
      END LOOP;
    END LOOP;
    RAISE NOTICE 'practice_areas.lawyer_ids still exists — profile_practice_areas is seeded by 20261001. Column left in place for reference.';
  END IF;
END $$;

-- ----------------------------------------------------------------------------
-- 3. Ensure profile_practice_areas has every seeded lawyer linked
-- ----------------------------------------------------------------------------
-- Safety net: if the 20261001 seed block didn't link a lawyer to any area,
-- try again using the email↔lid mapping from the seed VALUES. This is a
-- best-effort match by display_order (1→l1, 2→l2, ...).
INSERT INTO public.profile_practice_areas (profile_id, practice_area_id)
SELECT p.id, pa.id
FROM public.profiles p
CROSS JOIN public.practice_areas pa
WHERE p.role = 'lawyer' AND p.is_active = TRUE
  AND p.display_order IS NOT NULL
  AND EXISTS (
    SELECT 1 FROM unnest(pa.lawyer_ids) AS lid
    WHERE lid = 'l' || p.display_order::TEXT
  )
ON CONFLICT DO NOTHING;

-- ----------------------------------------------------------------------------
-- 4. Verify the public_lawyers view shows practice areas
-- ----------------------------------------------------------------------------
DO $$
DECLARE v_count INTEGER;
BEGIN
  SELECT count(*) INTO v_count FROM public.public_lawyers WHERE jsonb_array_length(practice_areas) > 0;
  RAISE NOTICE 'public_lawyers with practice areas: %', v_count;
  IF v_count = 0 THEN
    RAISE WARNING 'No lawyers have linked practice areas. Check that profile_practice_areas is populated.';
  END IF;
END $$;

-- ----------------------------------------------------------------------------
-- 5. Comment the legacy tables
-- ----------------------------------------------------------------------------
-- NOTE: PostgreSQL's COMMENT ON TABLE has no IF EXISTS variant, so each comment
-- is guarded on the table actually existing.
DO $$
BEGIN
  IF to_regclass('public.lawyers_legacy') IS NOT NULL THEN
    COMMENT ON TABLE public.lawyers_legacy IS 'LEGACY: lawyer data now lives on profiles. Kept as backup.';
  END IF;
  IF to_regclass('public.saved_lawyers_legacy') IS NOT NULL THEN
    COMMENT ON TABLE public.saved_lawyers_legacy IS 'LEGACY: favourites now use localStorage. Kept as backup.';
  END IF;
  IF to_regclass('public.consultations_legacy') IS NOT NULL THEN
    COMMENT ON TABLE public.consultations_legacy IS 'LEGACY: duplicated inquiries+appointments. Kept as backup.';
  END IF;
END $$;


-- ############################################################################
-- ## 6/17  20261003_integrity_hardening.sql
-- ############################################################################
-- ============================================================================
-- 20261003  Integrity hardening
-- ============================================================================
-- Run AFTER 20261001_consolidated_access_control.sql. Safe to re-run.
--
-- Closes six holes found in the role audit:
--
--   1. Last-admin guard. Nothing stopped an admin demoting or deactivating
--      their own account, which could leave the firm with no administrator
--      and no way back in (there is no reactivation screen).
--   2. Deactivation was cosmetic. signIn() never checked is_active, so a
--      "deactivated" user could still log in and still hold their role in
--      every RLS policy. The role helpers now return nothing for inactive
--      accounts, so the database itself denies them.
--   3. The audit trail was half-forgeable. Trigger-written rows (break-glass,
--      matter transitions, profile edits) are trustworthy; rows written from
--      the browser are self-reported. They were indistinguishable. Rows are
--      now stamped with their source.
--   4. profiles.email could be changed by an admin from the browser console
--      while auth.users.email stayed stale, silently breaking login.
--   5. The audit trail could be erased outright. cleanup_old_audit_logs() was
--      SECURITY DEFINER and granted to PUBLIC (which includes anon), so any
--      visitor could run cleanup_old_audit_logs(0) and delete the whole
--      history, break-glass records included.
--   6. (application-side) see the matching UI guards in ClientPortal.tsx.
-- ============================================================================


-- ----------------------------------------------------------------------------
-- 1. Audit rows carry their source
-- ----------------------------------------------------------------------------
ALTER TABLE public.audit_logs
  ADD COLUMN IF NOT EXISTS source TEXT NOT NULL DEFAULT 'client';

DO $$ BEGIN
  ALTER TABLE public.audit_logs
    ADD CONSTRAINT audit_logs_source_check CHECK (source IN ('trigger', 'client'));
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

COMMENT ON COLUMN public.audit_logs.source IS
  'trigger = written by a database trigger via private.write_audit (trustworthy). '
  'client = written by the browser (self-reported, cannot be verified).';

-- Re-create the audit writer so its rows are stamped as trigger-written.
CREATE OR REPLACE FUNCTION private.write_audit(
  p_event TEXT, p_desc TEXT, p_type TEXT, p_id TEXT,
  p_meta JSONB DEFAULT NULL, p_success BOOLEAN DEFAULT TRUE
) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $$
DECLARE v_uid UUID := auth.uid(); v_email TEXT; v_role TEXT;
BEGIN
  IF v_uid IS NULL THEN RETURN; END IF;  -- SQL editor / service role
  SELECT p.email, p.role::TEXT INTO v_email, v_role FROM public.profiles p WHERE p.id = v_uid;
  -- Declares this write as trigger-originated. private.stamp_audit_source()
  -- reads and clears it; a browser cannot set it.
  PERFORM set_config('app.audit_source', 'trigger', TRUE);
  INSERT INTO public.audit_logs
    (user_id, user_email, user_role, event_type, event_description, resource_type, resource_id, metadata, success, source)
  VALUES (v_uid, v_email, v_role, p_event, p_desc, p_type, p_id, p_meta, p_success, 'trigger');
EXCEPTION WHEN OTHERS THEN
  -- Audit logging must never block the operation being audited (a profile edit,
  -- a matter update, ...). If audit_logs has drifted from the expected shape we
  -- warn loudly and let the caller continue.
  RAISE WARNING 'audit row skipped: %', SQLERRM;
END $$;
REVOKE ALL ON FUNCTION private.write_audit(TEXT,TEXT,TEXT,TEXT,JSONB,BOOLEAN) FROM PUBLIC;

-- There is a SECOND audit writer. log_auth_event() (from 20260916) fires on
-- every insert/update of public.profiles and writes ACCOUNT_CREATED,
-- ROLE_CHANGED and ACCOUNT_DEACTIVATED rows with a bare INSERT, so those rows
-- were landing as source='client' and would have been displayed as
-- "self-reported by the browser" in the admin audit screen. Re-create it
-- stamped as trigger-written.
--
-- It deliberately does NOT route through private.write_audit(): that function
-- returns early when auth.uid() IS NULL, and profile rows are created by
-- handle_new_user() running as the service role, so ACCOUNT_CREATED would be
-- lost entirely.
--
-- private.stamp_audit_source() clears the flag after every row, so each insert
-- below has to declare itself again.
CREATE OR REPLACE FUNCTION public.log_auth_event()
RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM set_config('app.audit_source', 'trigger', TRUE);
    INSERT INTO public.audit_logs
      (user_id, user_email, event_type, event_description, success, source)
    VALUES
      (NEW.id, NEW.email, 'ACCOUNT_CREATED',
       'User account created: ' || NEW.email, TRUE, 'trigger');
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.role IS DISTINCT FROM NEW.role THEN
      PERFORM set_config('app.audit_source', 'trigger', TRUE);
      INSERT INTO public.audit_logs
        (user_id, user_email, user_role, event_type, event_description,
         resource_type, resource_id, metadata, success, source)
      VALUES
        (NEW.id, NEW.email, NEW.role::TEXT, 'ROLE_CHANGED',
         'User role changed from ' || OLD.role || ' to ' || NEW.role,
         'user', NEW.id::TEXT,
         jsonb_build_object('old_role', OLD.role, 'new_role', NEW.role),
         TRUE, 'trigger');
    END IF;

    IF OLD.is_active = TRUE AND NEW.is_active = FALSE THEN
      PERFORM set_config('app.audit_source', 'trigger', TRUE);
      INSERT INTO public.audit_logs
        (user_id, user_email, user_role, event_type, event_description,
         resource_type, resource_id, success, source)
      VALUES
        (NEW.id, NEW.email, NEW.role::TEXT, 'ACCOUNT_DEACTIVATED',
         'User account deactivated: ' || NEW.email,
         'user', NEW.id::TEXT, TRUE, 'trigger');
    END IF;
  END IF;

  RETURN NEW;
END $$;

-- Backfill: the browser never writes ROLE_CHANGED or ACCOUNT_DEACTIVATED
-- (checked against src/lib/services/audit.ts and every call site), so any such
-- row that predates this migration came from the trigger above.
-- ACCOUNT_CREATED is deliberately left alone: both the trigger and
-- auth.ts:107 write it, and guessing wrong would mark a browser row as
-- trustworthy.
UPDATE public.audit_logs
   SET source = 'trigger'
 WHERE source = 'client'
   AND event_type IN ('ROLE_CHANGED', 'ACCOUNT_DEACTIVATED');

-- The browser must not be able to claim it was a trigger.
--
-- audit_logs has an INSERT policy of WITH CHECK (auth.uid() = user_id), and the
-- source column is just another column, so a signed-in user could insert
--   INSERT INTO audit_logs (..., source) VALUES (..., 'trigger');
-- and mint a row that the admin screen shows as authoritative — for example a
-- fake CONFIDENTIAL_BREAK_GLASS entry to muddy the record of who opened a
-- privileged file.
--
-- auth.uid() cannot be the discriminator: private.write_audit() is SECURITY
-- DEFINER but still sees the caller's JWT, so it would be downgraded too. Use a
-- transaction-local flag instead. PostgREST gives a client no way to set a
-- custom GUC, so only our own functions can raise it, and the trigger lowers it
-- again immediately so one declared write cannot vouch for the next.
CREATE OR REPLACE FUNCTION private.stamp_audit_source() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $$
DECLARE v_declared TEXT := current_setting('app.audit_source', TRUE);
BEGIN
  IF v_declared IS DISTINCT FROM 'trigger' THEN
    NEW.source := 'client';
  END IF;
  PERFORM set_config('app.audit_source', '', TRUE);
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS audit_logs_stamp_source ON public.audit_logs;
CREATE TRIGGER audit_logs_stamp_source BEFORE INSERT ON public.audit_logs
FOR EACH ROW EXECUTE FUNCTION private.stamp_audit_source();


-- ----------------------------------------------------------------------------
-- 2. Deactivated accounts lose their role everywhere
-- ----------------------------------------------------------------------------
-- Every role-gated policy in the schema routes through one of these three
-- helpers, so returning nothing here denies an inactive account access to
-- everything except its own profile row (which uses auth.uid() = id directly).
CREATE OR REPLACE FUNCTION private.get_user_role()
RETURNS public.user_role
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $$
  SELECT p.role
  FROM public.profiles AS p
  WHERE p.id = (SELECT auth.uid())
    AND COALESCE(p.is_active, TRUE)
    AND p.deleted_at IS NULL
  LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION private.is_admin()
RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles AS p
    WHERE p.id = (SELECT auth.uid())
      AND p.role = 'admin'::public.user_role
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
  );
$$;

CREATE OR REPLACE FUNCTION private.is_lawyer_or_admin()
RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles AS p
    WHERE p.id = (SELECT auth.uid())
      AND p.role IN ('lawyer'::public.user_role, 'admin'::public.user_role)
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
  );
$$;

REVOKE ALL ON FUNCTION private.get_user_role() FROM PUBLIC;
REVOKE ALL ON FUNCTION private.is_admin() FROM PUBLIC;
REVOKE ALL ON FUNCTION private.is_lawyer_or_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.get_user_role() TO authenticated;
GRANT EXECUTE ON FUNCTION private.is_admin() TO authenticated;
GRANT EXECUTE ON FUNCTION private.is_lawyer_or_admin() TO authenticated;


-- ----------------------------------------------------------------------------
-- 3. The firm must always keep at least one active administrator
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION private.guard_last_admin() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_remaining INT;
BEGIN
  -- Only fire when an *active* admin is being removed from the admin pool.
  IF OLD.role = 'admin'::public.user_role
     AND COALESCE(OLD.is_active, TRUE)
     AND (NEW.role IS DISTINCT FROM 'admin'::public.user_role
          OR NOT COALESCE(NEW.is_active, TRUE)
          OR NEW.deleted_at IS NOT NULL) THEN

    SELECT count(*) INTO v_remaining
    FROM public.profiles p
    WHERE p.role = 'admin'::public.user_role
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
      AND p.id <> OLD.id;

    IF v_remaining = 0 THEN
      RAISE EXCEPTION
        'This is the last active administrator. Promote another account to admin before changing this one.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION private.guard_last_admin_delete() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_remaining INT;
BEGIN
  IF OLD.role = 'admin'::public.user_role AND COALESCE(OLD.is_active, TRUE) THEN
    SELECT count(*) INTO v_remaining
    FROM public.profiles p
    WHERE p.role = 'admin'::public.user_role
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
      AND p.id <> OLD.id;

    IF v_remaining = 0 THEN
      RAISE EXCEPTION
        'This is the last active administrator and cannot be deleted. Promote another account first.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN OLD;
END $$;

DROP TRIGGER IF EXISTS profiles_last_admin ON public.profiles;
CREATE TRIGGER profiles_last_admin BEFORE UPDATE ON public.profiles
FOR EACH ROW EXECUTE FUNCTION private.guard_last_admin();

DROP TRIGGER IF EXISTS profiles_last_admin_delete ON public.profiles;
CREATE TRIGGER profiles_last_admin_delete BEFORE DELETE ON public.profiles
FOR EACH ROW EXECUTE FUNCTION private.guard_last_admin_delete();


-- ----------------------------------------------------------------------------
-- 4. Email is owned by auth.users, never by profiles
-- ----------------------------------------------------------------------------
-- Changing profiles.email alone silently desynchronises the login identity from
-- the displayed one. The app already hides the field; this makes it real.
-- auth.uid() IS NULL means the SQL editor / service role, which is the one path
-- that legitimately needs to repair a drifted address.
CREATE OR REPLACE FUNCTION private.guard_profile_update() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF NEW.date_of_birth IS NOT NULL AND (NEW.date_of_birth > CURRENT_DATE OR NEW.date_of_birth < DATE '1900-01-01') THEN
    RAISE EXCEPTION 'Birthday must be a real past date';
  END IF;

  IF NEW.email IS DISTINCT FROM OLD.email AND auth.uid() IS NOT NULL THEN
    RAISE EXCEPTION 'Email addresses cannot be changed from the app. Contact the firm.';
  END IF;

  IF auth.uid() IS NULL OR private.is_admin() THEN RETURN NEW; END IF;

  IF NEW.role IS DISTINCT FROM OLD.role
     OR NEW.is_active IS DISTINCT FROM OLD.is_active
     OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
     OR NEW.position IS DISTINCT FROM OLD.position
     OR NEW.display_order IS DISTINCT FROM OLD.display_order THEN
    RAISE EXCEPTION 'You cannot change role, email, status, position or display order. Contact the firm.';
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS profiles_guard_update ON public.profiles;
CREATE TRIGGER profiles_guard_update BEFORE UPDATE ON public.profiles
FOR EACH ROW EXECUTE FUNCTION private.guard_profile_update();


-- ----------------------------------------------------------------------------
-- 5. The audit trail cannot be erased by the people it audits
-- ----------------------------------------------------------------------------
-- cleanup_old_audit_logs() was SECURITY DEFINER (so it bypasses the RLS
-- policies on audit_logs) and was granted to PUBLIC, which in this schema
-- includes anon. Any visitor who knew the function name could run
--   SELECT public.cleanup_old_audit_logs(0);
-- and delete the firm's entire audit history -- including the
-- CONFIDENTIAL_BREAK_GLASS rows that record who opened a privileged client
-- file. It also had no search_path pin, which is a hijack risk in a
-- SECURITY DEFINER function.
--
-- Now: admins only, a hard 30-day floor, and a pinned search_path.
CREATE OR REPLACE FUNCTION public.cleanup_old_audit_logs(days_to_keep INTEGER DEFAULT 365)
RETURNS INTEGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $$
DECLARE deleted_count INTEGER;
BEGIN
  -- auth.uid() IS NULL means service role / SQL editor (the cron path).
  IF auth.uid() IS NOT NULL AND NOT private.is_admin() THEN
    RAISE EXCEPTION 'Only an administrator can prune the audit trail';
  END IF;

  IF days_to_keep IS NULL OR days_to_keep < 30 THEN
    RAISE EXCEPTION 'Refusing to delete audit rows newer than 30 days (asked for %)', days_to_keep;
  END IF;

  DELETE FROM public.audit_logs
   WHERE created_at < NOW() - make_interval(days => days_to_keep);

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END $$;

REVOKE ALL ON FUNCTION public.cleanup_old_audit_logs(INTEGER) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.cleanup_old_audit_logs(INTEGER) FROM anon;
REVOKE ALL ON FUNCTION public.cleanup_old_audit_logs(INTEGER) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.cleanup_old_audit_logs(INTEGER) TO service_role;


-- ----------------------------------------------------------------------------
-- 6. Report what is now in force
-- ----------------------------------------------------------------------------
DO $$
DECLARE v_admins INT; v_sources TEXT;
BEGIN
  SELECT count(*) INTO v_admins FROM public.profiles
  WHERE role = 'admin' AND COALESCE(is_active, TRUE) AND deleted_at IS NULL;
  SELECT string_agg(DISTINCT source, ', ') INTO v_sources FROM public.audit_logs;

  RAISE NOTICE 'Active administrators: %', v_admins;
  IF v_admins = 0 THEN
    RAISE WARNING 'There is no active administrator. Promote one before relying on the admin screens.';
  END IF;
  RAISE NOTICE 'audit_logs sources present: %', COALESCE(v_sources, '(none yet)');
END $$;


-- ############################################################################
-- ## 7/17  20261004_client_messaging.sql
-- ############################################################################
-- ============================================================================
-- 20261004  Client messaging on matters
-- ============================================================================
-- Run AFTER 20261003_integrity_hardening.sql. Safe to re-run.
--
-- The client could read client-visible notes but could not write one:
--
--   matter_notes_insert required is_matter_lawyer_team(matter_id)
--     OR (visibility = 'client' AND is_admin())
--
-- so a client replying to their lawyer was rejected by RLS. There was no way
-- for a client to say anything inside the portal at all — the firm's only
-- stated alternative was email.
--
-- Two things change:
--
--   1. A client may insert a note on a matter they own, and only at
--      visibility = 'client'. They cannot write internal notes (which they
--      are not allowed to read anyway), and they cannot write to a matter
--      that is not theirs.
--   2. private.on_matter_note_insert() notified the client on every
--      client-visible note. When the client is the author that is a no-op
--      (create_notification already refuses to notify the actor), so the
--      lawyer heard nothing. A client-authored note now notifies the
--      assigned lawyer and the rest of the matter team.
--
-- No new table and no new column: matter_notes already had the visibility
-- column and a client-visible SELECT policy.
-- ============================================================================


-- ----------------------------------------------------------------------------
-- 1. Clients may post client-visible notes on their own matters
-- ----------------------------------------------------------------------------
-- Kept as a separate policy from matter_notes_insert rather than widening that
-- one, so the lawyer/admin rule stays legible and a future edit to one cannot
-- silently loosen the other.
DROP POLICY IF EXISTS matter_notes_insert_client ON public.matter_notes;
CREATE POLICY matter_notes_insert_client ON public.matter_notes
FOR INSERT TO authenticated
WITH CHECK (
  author_id = (SELECT auth.uid())
  AND visibility = 'client'
  AND EXISTS (
    SELECT 1 FROM public.matters m
    WHERE m.id = matter_notes.matter_id
      AND m.client_id = (SELECT auth.uid())
  )
);


-- ----------------------------------------------------------------------------
-- 2. A client's message notifies the lawyer team, not the client
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION private.on_matter_note_insert() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_client   UUID;
  v_assigned UUID;
  v_member   UUID;
  v_is_client_author BOOLEAN;
BEGIN
  SELECT m.client_id, m.lawyer_id INTO v_client, v_assigned
  FROM public.matters m WHERE m.id = NEW.matter_id;

  v_is_client_author := (NEW.author_id IS NOT DISTINCT FROM v_client);

  INSERT INTO public.matter_events(matter_id, event_type, title, actor_id, visible_to_client)
  VALUES (
    NEW.matter_id,
    'note',
    CASE
      WHEN v_is_client_author THEN 'Message from the client'
      WHEN NEW.visibility = 'client' THEN 'Update from your lawyer'
      ELSE 'Internal note added'
    END,
    NEW.author_id,
    NEW.visibility = 'client'
  );

  IF NEW.visibility = 'client' THEN
    IF v_is_client_author THEN
      -- The client wrote it. Tell the assigned lawyer, then everyone else on
      -- the team. create_notification() skips the author, so if a team member
      -- wrote the note they are not notified about their own message.
      PERFORM private.create_notification(
        v_assigned, 'New message from your client', left(NEW.body, 140), 'info', 'matters');

      FOR v_member IN
        SELECT mm.lawyer_id FROM public.matter_members mm
        WHERE mm.matter_id = NEW.matter_id
          AND mm.lawyer_id IS DISTINCT FROM v_assigned
      LOOP
        PERFORM private.create_notification(
          v_member, 'New message from a client', left(NEW.body, 140), 'info', 'matters');
      END LOOP;
    ELSE
      PERFORM private.create_notification(
        v_client, 'New update on your matter', left(NEW.body, 140), 'info', 'matters');
    END IF;
  END IF;

  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS matter_notes_after_insert ON public.matter_notes;
CREATE TRIGGER matter_notes_after_insert AFTER INSERT ON public.matter_notes
FOR EACH ROW EXECUTE FUNCTION private.on_matter_note_insert();


-- ----------------------------------------------------------------------------
-- 3. Report what is now in force
-- ----------------------------------------------------------------------------
DO $$
DECLARE v_policy BOOLEAN;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'matter_notes'
      AND policyname = 'matter_notes_insert_client'
  ) INTO v_policy;

  RAISE NOTICE 'Clients can post client-visible matter notes: %', v_policy;
END $$;


-- ############################################################################
-- ## 8/17  20261005_security_advisor_fixes.sql
-- ############################################################################
-- ============================================================================
-- 20261005  Security advisor fixes
-- ============================================================================
-- Triage of the Supabase Database Linter report. Each section names the
-- advisory it clears and says whether the finding was a real problem or a
-- by-design pattern the linter cannot see the intent behind.
--
-- REAL PROBLEMS FIXED HERE
--   * rls_disabled_in_public (x3)          legacy tables readable by anyone
--   * public_execute_security_definer      anon could deactivate any account
--   * function_search_path_mutable (x3)    hijackable function bodies
--   * public_bucket_allows_listing         lawyer-photos could be enumerated
--   * rls_policy_always_true (x3)          forged inquiries, open draft reads,
--                                          inquiries_insert_public leftover
--   * auth_rls_initplan (x30+)             per-row auth.uid() re-evaluation
--   * unindexed_foreign_keys (x9)          seq-scan on every parent delete
--
-- DELIBERATELY NOT "FIXED" — see section 13 for the reasoning
--   * security_definer_view (public_lawyers)  it IS the public boundary
--   * multiple_permissive_policies            pairs that encode two rules
--   * unused_index                            no traffic history to judge on
--   * leaked_password_protection              an Auth dashboard setting
--
-- Safe to re-run: every statement is guarded or idempotent.
-- ============================================================================


-- ----------------------------------------------------------------------------
-- 1. rls_disabled_in_public — the *_legacy tables
-- ----------------------------------------------------------------------------
-- 20261002 renamed these out of the way and then DISABLED RLS on them "so they
-- stop interfering with policy audits". Disabling RLS does not restrict
-- anything: Supabase grants anon/authenticated blanket table privileges, and
-- RLS is the only gate. So every anonymous visitor could read the old lawyer
-- roster, the old favourites, and the old consultation requests.
--
-- They are kept as a read-only backup, so they are locked down rather than
-- dropped. Nothing in src/ has ever read them.
--
-- To reclaim the space once the backup is no longer wanted:
--   DROP TABLE public.lawyers_legacy, public.saved_lawyers_legacy, public.consultations_legacy;
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['lawyers_legacy', 'saved_lawyers_legacy', 'consultations_legacy'] LOOP
    IF to_regclass('public.' || t) IS NOT NULL THEN
      EXECUTE format('REVOKE ALL ON TABLE public.%I FROM anon, authenticated', t);
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
      -- Belt and braces: if a policy is ever added back by accident, RLS is
      -- still on and there is still no grant for the API roles to use.
      RAISE NOTICE 'Locked down public.%', t;
    END IF;
  END LOOP;
END $$;


-- ----------------------------------------------------------------------------
-- 2. Retire a resurrected public.consultations
-- ----------------------------------------------------------------------------
-- 20261002 renamed public.consultations to consultations_legacy. But
-- 20260917 declares `CREATE TABLE IF NOT EXISTS public.consultations`, so any
-- run of the full migration chain AFTER that rename re-creates the table from
-- scratch — empty, but carrying consultations_insert_policy (anon INSERT,
-- WITH CHECK true). The owner only ever pastes the combined file, which does
-- not include 20260917, so the live project is unaffected. This closes the
-- hole for anyone who ever replays the whole chain.
DO $$
DECLARE pol RECORD;
BEGIN
  IF to_regclass('public.consultations') IS NOT NULL THEN
    FOR pol IN SELECT policyname FROM pg_policies
               WHERE schemaname = 'public' AND tablename = 'consultations'
    LOOP
      EXECUTE format('DROP POLICY IF EXISTS %I ON public.consultations', pol.policyname);
    END LOOP;
    REVOKE ALL ON TABLE public.consultations FROM anon, authenticated;
    ALTER TABLE public.consultations ENABLE ROW LEVEL SECURITY;
    COMMENT ON TABLE public.consultations IS
      'RESURRECTED BY A MIGRATION REPLAY. Superseded by inquiries + appointments; do not use.';
    RAISE NOTICE 'Retired a resurrected public.consultations';
  END IF;
END $$;


-- ----------------------------------------------------------------------------
-- 3. Function search_path
-- ----------------------------------------------------------------------------
-- update_updated_at was declared without a pinned search_path in
-- schema-production.sql. It is not SECURITY DEFINER, but it runs inside the
-- transaction of whoever fired the trigger, so a caller-controlled search_path
-- still decides how NOW() resolves. Pin it.
--
-- NOW() keeps working with an empty path: pg_catalog is always searched
-- implicitly, first.
CREATE OR REPLACE FUNCTION public.update_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END $$;


-- ----------------------------------------------------------------------------
-- 4. soft_delete_profile / reactivate_profile — anon could deactivate anyone
-- ----------------------------------------------------------------------------
-- Both are SECURITY DEFINER, both update public.profiles, and neither checked
-- who was calling. They were created with no explicit ACL, so PostgreSQL's
-- default applied: EXECUTE to PUBLIC. In this schema PUBLIC includes anon.
--
--   POST /rest/v1/rpc/soft_delete_profile  {"user_id": "<any uuid>"}
--
-- was therefore a working, unauthenticated "deactivate this account" call for
-- every account in the firm — including admins. reactivate_profile had the
-- mirror problem: it could bring a deliberately disabled account back.
--
-- Nothing in src/ calls either one; they exist for the SQL editor.
--
-- GUARDED ON EXISTENCE, and that matters. These two come from
-- 20260916_add_soft_delete_support.sql, which is NOT part of
-- APPLY_PENDING_MIGRATIONS.sql. Probing the live project confirms it:
--
--   POST /rest/v1/rpc/soft_delete_profile  ->  404 PGRST202 (no such function)
--   POST /rest/v1/rpc/cleanup_old_audit_logs -> 401 42501 (exists, denied)
--
-- A bare CREATE OR REPLACE here would therefore have ADDED two unused,
-- account-mutating functions to a database that did not have them. They are
-- hardened only where they already exist, so a replay of the full migration
-- chain closes the hole and the live project is left alone.
DO $$
BEGIN
  IF to_regprocedure('public.soft_delete_profile(uuid)') IS NOT NULL THEN
    EXECUTE $fn$
      CREATE OR REPLACE FUNCTION public.soft_delete_profile(user_id UUID)
      RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $body$
      BEGIN
        -- auth.uid() IS NULL means the SQL editor or service_role, same
        -- convention as cleanup_old_audit_logs.
        IF auth.uid() IS NOT NULL AND NOT private.is_admin() THEN
          RAISE EXCEPTION 'Only an administrator can deactivate an account';
        END IF;

        UPDATE public.profiles
           SET is_active = FALSE, deleted_at = NOW(), updated_at = NOW()
         WHERE id = user_id;
      END $body$;
    $fn$;
    -- REVOKE ... FROM PUBLIC is the one that matters: the EXECUTE anon
    -- inherited came from the PUBLIC pseudo-role, not from a grant to anon.
    REVOKE ALL ON FUNCTION public.soft_delete_profile(UUID) FROM PUBLIC, anon;
    GRANT EXECUTE ON FUNCTION public.soft_delete_profile(UUID) TO authenticated, service_role;
    RAISE NOTICE 'Hardened public.soft_delete_profile()';
  END IF;

  IF to_regprocedure('public.reactivate_profile(uuid)') IS NOT NULL THEN
    EXECUTE $fn$
      CREATE OR REPLACE FUNCTION public.reactivate_profile(user_id UUID)
      RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $body$
      BEGIN
        IF auth.uid() IS NOT NULL AND NOT private.is_admin() THEN
          RAISE EXCEPTION 'Only an administrator can reactivate an account';
        END IF;

        UPDATE public.profiles
           SET is_active = TRUE, deleted_at = NULL, updated_at = NOW()
         WHERE id = user_id;
      END $body$;
    $fn$;
    REVOKE ALL ON FUNCTION public.reactivate_profile(UUID) FROM PUBLIC, anon;
    GRANT EXECUTE ON FUNCTION public.reactivate_profile(UUID) TO authenticated, service_role;
    RAISE NOTICE 'Hardened public.reactivate_profile()';
  END IF;
END $$;


-- ----------------------------------------------------------------------------
-- 5. log_auth_event — trigger function exposed over the API
-- ----------------------------------------------------------------------------
-- SECURITY DEFINER, in the public schema, therefore callable as
-- POST /rest/v1/rpc/log_auth_event. It is a trigger function so a direct call
-- errors out harmlessly, but there is no reason for it to be reachable at all.
--
-- Revoking EXECUTE does NOT stop the trigger from firing: PostgreSQL checks
-- EXECUTE when the trigger is CREATED, not each time it fires. Section 10
-- asserts that audit rows still appear after this revoke.
REVOKE ALL ON FUNCTION public.log_auth_event() FROM PUBLIC, anon, authenticated;


-- ----------------------------------------------------------------------------
-- 6. public_bucket_allows_listing — lawyer-photos
-- ----------------------------------------------------------------------------
-- A public bucket serves objects over its public URL without consulting RLS,
-- so the SELECT policy bought nothing except the ability to enumerate every
-- file in the bucket. Nothing in src/ reads or writes this bucket at all, and
-- profiles.profile_image already points at plain URLs, so the policy is simply
-- removed rather than narrowed.
--
-- If a photo manager is ever built, add it back as:
--   CREATE POLICY lawyer_photos_select ON storage.objects FOR SELECT
--     TO authenticated USING (bucket_id = 'lawyer-photos' AND (SELECT private.is_admin()));
DROP POLICY IF EXISTS lawyer_photos_select ON storage.objects;


-- ----------------------------------------------------------------------------
-- 7. rls_policy_always_true — inquiries INSERT
-- ----------------------------------------------------------------------------
-- WITH CHECK (true) let an anonymous visitor write any value into any column,
-- not just the ones the contact form sends. Two of those columns are not
-- harmless:
--   * assigned_to — insert an inquiry pre-assigned to a partner
--   * client_id   — insert an inquiry into ANOTHER user's portal, where it
--                   shows up as if the firm had logged it for them
--
-- The form (src/utils/api.ts) sends status 'New', no assigned_to, and
-- client_id either null or the signed-in user's own id. The policy now says
-- exactly that. (Only client_id: live inquiries has no user_id column, and an
-- earlier draft of this policy failed on the live project with
-- `42703 column "user_id" does not exist`.)
DROP POLICY IF EXISTS inquiries_insert_policy ON public.inquiries;
CREATE POLICY inquiries_insert_policy ON public.inquiries
FOR INSERT TO anon, authenticated
WITH CHECK (
  status = 'New'
  AND assigned_to IS NULL
  AND (client_id IS NULL OR client_id = (SELECT auth.uid()))
);


-- ----------------------------------------------------------------------------
-- 8. Redundant and always-true policies
-- ----------------------------------------------------------------------------
-- articles_authenticated_select (SELECT, authenticated, USING true) let any
-- signed-in client read unpublished drafts. It was also redundant: the
-- admin/author policy already covers everyone who should see a draft, and
-- articles_public_select covers the published ones. Dropping it clears both
-- rls_policy_always_true and the articles multiple-permissive-policies group.
DROP POLICY IF EXISTS articles_authenticated_select ON public.articles;

-- profile_practice_areas_public_select (SELECT, public, USING true) was for the
-- "Our Lawyers" page, but that page reads the public_lawyers view, and a view
-- runs with its owner's rights — it never consults this policy. The only
-- readers left are the admin and own-row policies below it.
DROP POLICY IF EXISTS profile_practice_areas_public_select ON public.profile_practice_areas;

-- inquiries_insert_public (INSERT, anon+authenticated, WITH CHECK true) is a
-- leftover from the ad-hoc schema the live project was built from. 20260918
-- drops it, but 20260918 is not part of this chain and never reached the live
-- project, and no other migration names it. It matters twice over: it trips
-- rls_policy_always_true, and because permissive policies OR together it
-- silently voids section 7 above — anyone could still write any status /
-- assigned_to / client_id into the inquiry queue. The live verification grid
-- caught it ("no always-true policy remains" = FAIL).
DROP POLICY IF EXISTS inquiries_insert_public ON public.inquiries;

-- Sweep anything else with a literal `true` predicate. The verification grid
-- asserts zero of these in public, so this enforces that invariant; on a
-- database built from this chain alone it is a no-op.
DO $$ DECLARE pol RECORD; n INT := 0; BEGIN
  FOR pol IN
    SELECT tablename, policyname FROM pg_policies
    WHERE schemaname = 'public'
      AND (btrim(COALESCE(qual,'')) = 'true' OR btrim(COALESCE(with_check,'')) = 'true')
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', pol.policyname, pol.tablename);
    RAISE NOTICE 'Dropped always-true policy %.%', pol.tablename, pol.policyname;
    n := n + 1;
  END LOOP;
  IF n > 0 THEN RAISE NOTICE 'Dropped % always-true policy(ies)', n; END IF;
END $$;


-- ----------------------------------------------------------------------------
-- 9. auth_rls_initplan — wrap auth.uid() so it is evaluated once, not per row
-- ----------------------------------------------------------------------------
-- A policy that calls auth.uid() directly is re-evaluated for every row the
-- planner considers. Wrapping it as (SELECT auth.uid()) turns it into an
-- InitPlan evaluated once per query. On a table of a few hundred rows this is
-- a rounding error; the reason to fix it anyway is that the rewrite is purely
-- mechanical and the linter output stays readable for the findings that matter.
--
-- Rewriting from pg_policies rather than from the migration files means the
-- live definitions are what gets fixed, so the result cannot drift from the
-- source the way a hand-copied CREATE POLICY would.
CREATE OR REPLACE FUNCTION private.wrap_auth_calls(p_expr TEXT) RETURNS TEXT
LANGUAGE plpgsql IMMUTABLE SET search_path = '' AS $$
DECLARE v TEXT := p_expr;
BEGIN
  IF v IS NULL THEN RETURN NULL; END IF;
  -- Park the already-wrapped forms behind markers. Without this, the
  -- bare-call replacement below would rewrite (SELECT auth.uid()) into
  -- (SELECT (SELECT auth.uid())) — still correct, but it never converges and
  -- the migration would keep reporting changes on every run.
  v := replace(v, 'SELECT auth.uid()',  E'\x01');
  v := replace(v, 'SELECT auth.jwt()',  E'\x02');
  v := replace(v, 'SELECT auth.role()', E'\x03');
  v := replace(v, 'auth.uid()',  '(SELECT auth.uid())');
  v := replace(v, 'auth.jwt()',  '(SELECT auth.jwt())');
  v := replace(v, 'auth.role()', '(SELECT auth.role())');
  v := replace(v, E'\x01', 'SELECT auth.uid()');
  v := replace(v, E'\x02', 'SELECT auth.jwt()');
  v := replace(v, E'\x03', 'SELECT auth.role()');
  RETURN v;
END $$;

DO $$
DECLARE
  pol     RECORD;
  v_qual  TEXT;
  v_check TEXT;
  v_roles TEXT;
  v_sql   TEXT;
  n       INT := 0;
BEGIN
  FOR pol IN
    SELECT tablename, policyname, permissive, roles, cmd, qual, with_check
    FROM pg_policies
    WHERE schemaname = 'public'
  LOOP
    v_qual  := private.wrap_auth_calls(pol.qual);
    v_check := private.wrap_auth_calls(pol.with_check);

    IF v_qual IS NOT DISTINCT FROM pol.qual
       AND v_check IS NOT DISTINCT FROM pol.with_check THEN
      CONTINUE;  -- already wrapped, or uses no auth helper at all
    END IF;

    -- pg_policies gives the deparsed predicate, so recreating the policy from
    -- it is a rename of the same expression, not a re-derivation of the rule.
    v_roles := (SELECT string_agg(quote_ident(r), ', ' ORDER BY r)
                FROM unnest(pol.roles) AS r);

    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', pol.policyname, pol.tablename);

    v_sql := format('CREATE POLICY %I ON public.%I AS %s FOR %s TO %s',
                    pol.policyname, pol.tablename, pol.permissive, pol.cmd, v_roles);
    IF v_qual  IS NOT NULL THEN v_sql := v_sql || format(' USING (%s)', v_qual); END IF;
    IF v_check IS NOT NULL THEN v_sql := v_sql || format(' WITH CHECK (%s)', v_check); END IF;

    EXECUTE v_sql;
    n := n + 1;
  END LOOP;

  RAISE NOTICE 'Rewrote % policy/policies to evaluate auth helpers once per query', n;
END $$;

DROP FUNCTION IF EXISTS private.wrap_auth_calls(TEXT);


-- ----------------------------------------------------------------------------
-- 10. unindexed_foreign_keys
-- ----------------------------------------------------------------------------
-- Every FK whose columns are not the leading columns of an index. The parent
-- side of ON DELETE then seq-scans the child table. Discovered from the
-- catalogue rather than listed by hand so it also covers whatever the live
-- project has that the migration chain does not.
DO $$
DECLARE
  fk      RECORD;
  v_name  TEXT;
  v_cols  TEXT;
  n       INT := 0;
BEGIN
  FOR fk IN
    SELECT c.conname,
           n.nspname,
           cl.relname,
           (SELECT string_agg(quote_ident(a.attname), ', ' ORDER BY k.ord)
              FROM unnest(c.conkey) WITH ORDINALITY AS k(attnum, ord)
              JOIN pg_attribute a
                ON a.attrelid = c.conrelid AND a.attnum = k.attnum) AS cols
    FROM pg_constraint c
    JOIN pg_class     cl ON cl.oid = c.conrelid
    JOIN pg_namespace n  ON n.oid  = cl.relnamespace
    WHERE c.contype = 'f'
      AND n.nspname = 'public'
      AND NOT EXISTS (
        SELECT 1 FROM pg_index i
        WHERE i.indrelid = c.conrelid
          AND i.indisvalid
          -- indkey is an int2vector, which casts to a ZERO-based array.
          -- Slicing it as [1:n] silently yields {} and every FK looks
          -- unindexed, so normalise through array_agg first.
          AND (SELECT array_agg(k ORDER BY ord)
               FROM unnest(i.indkey::smallint[]) WITH ORDINALITY AS t(k, ord))
              [1:array_length(c.conkey, 1)] = c.conkey
      )
  LOOP
    v_name := left('idx_fk_' || fk.conname, 63);
    v_cols := fk.cols;

    IF NOT EXISTS (
      SELECT 1 FROM pg_class ic
      JOIN pg_namespace inn ON inn.oid = ic.relnamespace
      WHERE ic.relname = v_name AND inn.nspname = fk.nspname
    ) THEN
      EXECUTE format('CREATE INDEX %I ON %I.%I (%s)',
                     v_name, fk.nspname, fk.relname, v_cols);
      n := n + 1;
    END IF;
  END LOOP;

  RAISE NOTICE 'Created % missing foreign-key index(es)', n;
END $$;


-- ----------------------------------------------------------------------------
-- 11. Explicit grants, so the chain stops depending on project defaults
-- ----------------------------------------------------------------------------
-- Supabase grants anon/authenticated blanket table privileges through
-- ALTER DEFAULT PRIVILEGES, but that only covers objects created by the roles
-- it was configured for. Every table and function here then relies on a
-- project-level setting that is invisible from the migrations and impossible to
-- reproduce locally — and when it is not in force the failure is confusing:
-- a missing GRANT on a table the policies DO cover shows up as 42501
-- "permission denied for table", which PostgREST reports as **403 on a plain
-- SELECT** rather than as an empty result.
--
-- These grants are already implied on a correctly-configured project, so on
-- most databases this section changes nothing. It exists so the chain is
-- self-sufficient. RLS is still the gate — these grants only let it run.

-- 11a. The four tables 20261001 creates. It revokes them from anon but leaves
-- the grant to authenticated to the project default.
GRANT SELECT, INSERT, UPDATE, DELETE
  ON public.matter_members, public.matter_notes, public.matter_events,
     public.confidential_access_grants
  TO authenticated, service_role;
REVOKE ALL ON public.matter_members, public.matter_notes, public.matter_events,
  public.confidential_access_grants FROM anon;

-- 11b. The public contact form is anonymous. inquiries_insert_policy is
-- TO anon, authenticated, and src/utils/api.ts deliberately does NOT send
-- inquiry_number — it relies on the column DEFAULT. A DEFAULT expression runs
-- as the inserting role, so an anonymous submission needs EXECUTE on the
-- function and USAGE on the sequence it draws from. schema-production.sql
-- grants both to authenticated only.
--
-- Guarded, because these come from schema-production.sql, which is the live
-- database's original base rather than part of this chain.
DO $$
BEGIN
  IF to_regprocedure('public.generate_inquiry_number()') IS NOT NULL THEN
    GRANT EXECUTE ON FUNCTION public.generate_inquiry_number() TO anon, authenticated;
  END IF;
  IF to_regclass('public.inquiry_number_seq') IS NOT NULL THEN
    GRANT USAGE, SELECT ON SEQUENCE public.inquiry_number_seq TO anon, authenticated;
  END IF;

  -- Same shape for matters, for symmetry: generate_matter_number() is only
  -- reachable by admins, who are authenticated, but the sequence grant is the
  -- same class of hidden dependency.
  IF to_regprocedure('public.generate_matter_number()') IS NOT NULL THEN
    GRANT EXECUTE ON FUNCTION public.generate_matter_number() TO authenticated, service_role;
  END IF;
  IF to_regclass('public.matter_number_seq') IS NOT NULL THEN
    GRANT USAGE, SELECT ON SEQUENCE public.matter_number_seq TO authenticated, service_role;
  END IF;
END $$;

-- 11c. The `private` schema itself. 20261001 creates it with CREATE SCHEMA IF
-- NOT EXISTS and grants nothing on it, and PostgreSQL gives a new schema to its
-- owner only — PUBLIC gets nothing. Every policy on matters, documents and the
-- three matter tables calls a private.* helper, and resolving that call
-- requires USAGE on the schema, so without this grant the tables answer
-- 42501 "permission denied for schema private", which PostgREST reports as 403.
--
-- Only schema-production.sql grants it today. That file is the live database's
-- original base rather than part of this chain (see 11b), so the chain must not
-- rely on it: a fresh database built from migrations alone would break here.
DO $$
BEGIN
  IF to_regnamespace('private') IS NOT NULL THEN
    REVOKE ALL ON SCHEMA private FROM PUBLIC, anon;
    GRANT USAGE ON SCHEMA private TO authenticated, service_role;
  END IF;
END $$;


-- ----------------------------------------------------------------------------
-- 12. Verify what is now in force
-- ----------------------------------------------------------------------------
-- Read the output of this block: it is the answer to "did the paste work".
DO $$
DECLARE
  v_leaky    TEXT;
  v_definer  TEXT;
  v_true     TEXT;
  v_mutable  TEXT;
  v_listable TEXT;
  v_audited  INT;
  v_schema   TEXT;
BEGIN
  SELECT string_agg(c.relname, ', ') INTO v_leaky
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind = 'r' AND NOT c.relrowsecurity
    AND (has_table_privilege('anon', c.oid, 'SELECT')
      OR has_table_privilege('authenticated', c.oid, 'SELECT'));

  SELECT string_agg(p.proname, ', ') INTO v_definer
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.prosecdef
    AND has_function_privilege('anon', p.oid, 'EXECUTE');

  SELECT string_agg(tablename || '.' || policyname, ', ') INTO v_true
  FROM pg_policies
  WHERE schemaname = 'public'
    AND (btrim(COALESCE(qual, '')) = 'true' OR btrim(COALESCE(with_check, '')) = 'true');

  SELECT string_agg(p.proname, ', ') INTO v_mutable
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.prokind = 'f'
    AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.objid = p.oid AND d.deptype = 'e')
    AND NOT EXISTS (SELECT 1 FROM unnest(COALESCE(p.proconfig, '{}'::text[])) AS c
                    WHERE c LIKE 'search_path=%');

  SELECT string_agg(b.id, ', ') INTO v_listable
  FROM storage.buckets b
  JOIN pg_policies p ON p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd = 'SELECT'
  WHERE b.public AND p.roles && ARRAY['anon', 'public']::name[]
    AND (COALESCE(p.qual, '') NOT LIKE '%bucket_id%'
      OR COALESCE(p.qual, '') LIKE '%' || b.id || '%');

  SELECT count(*) INTO v_audited FROM public.audit_logs WHERE event_type = 'ACCOUNT_CREATED';

  SELECT CASE
           WHEN to_regnamespace('private') IS NULL THEN 'schema missing'
           WHEN NOT has_schema_privilege('authenticated', 'private', 'USAGE') THEN 'authenticated cannot USE it'
           WHEN has_schema_privilege('anon', 'private', 'USAGE') THEN 'anon can USE it'
         END INTO v_schema;

  RAISE NOTICE '--------------------------------------------------------------';
  RAISE NOTICE 'RLS off and API-readable (want NULL)      : %', COALESCE(v_leaky,   'NULL');
  RAISE NOTICE 'anon-executable SECURITY DEFINER (NULL)   : %', COALESCE(v_definer, 'NULL');
  RAISE NOTICE 'always-true policies (want NULL)          : %', COALESCE(v_true,    'NULL');
  RAISE NOTICE 'mutable search_path functions (want NULL) : %', COALESCE(v_mutable, 'NULL');
  RAISE NOTICE 'public listable buckets (want NULL)       : %', COALESCE(v_listable,'NULL');
  RAISE NOTICE 'ACCOUNT_CREATED audit rows (must be > 0)  : %', v_audited;
  RAISE NOTICE 'private schema access (want NULL)         : %', COALESCE(v_schema,  'NULL');
  RAISE NOTICE '--------------------------------------------------------------';
END $$;


-- ----------------------------------------------------------------------------
-- 13. Findings left in place, on purpose
-- ----------------------------------------------------------------------------
-- These still appear in the dashboard after this migration. They are recorded
-- here so the next person reading the linter does not re-open them.
--
-- security_definer_view — public.public_lawyers
--   The view is the deliberate boundary between the public website and the
--   profiles table. Visitors cannot read profiles at all, so the "Our Lawyers"
--   page reads this view, which runs as its owner and selects ONLY the columns
--   the firm already publishes: name, position, bio, education, work email,
--   photo, city, and practice areas. No phone, address, or birthday.
--
--   Switching it to security_invoker would require granting anon a row policy
--   on profiles, which exposes every other column of every lawyer's profile.
--   That is strictly worse. If the linter result must be empty, the alternative
--   is to materialise the view into a table refreshed by trigger — more moving
--   parts than a marketing page is worth.
--
-- multiple_permissive_policies — 7 groups
--   Each group is two policies that encode two different rules for the same
--   action, not a duplicate that should have been dropped. Merging them with OR
--   would save one policy evaluation per row on tables with tens of rows.
--   Examples:
--     matters UPDATE      admin may edit anything; the assigned lawyer may
--                         advance their own matter (the guard trigger is what
--                         stops a lawyer reassigning it)
--     matter_notes INSERT a lawyer may write internal notes; a client may only
--                         write client-visible notes on their own matter
--   The one true duplicate, articles_authenticated_select, is dropped in
--   section 8.
--
-- unused_index — ~20 indexes
--   This is the one advisory that cannot be judged from the schema. "Unused"
--   means pg_stat_user_indexes has recorded no scans, which is also what a
--   freshly-reset counter or a low-traffic month looks like. Dropping an index
--   that is genuinely load-bearing is far more expensive than keeping one that
--   is not, and these are small tables. Revisit only with real traffic data.
--
-- leaked_password_protection — Auth setting, not a database object
--   Dashboard -> Authentication -> Sign In / Providers -> Email ->
--   "Prevent use of leaked passwords" -> ON. It checks new passwords against
--   HaveIBeenPwned. It costs one request per signup and cannot be set from SQL.
--
-- Related, found while checking the above and worth knowing:
--   schema-production.sql creates idx_profiles_role ON public.profiles(role),
--   and 20260918_content_tables.sql then tries to create a BETTER partial index
--   under the SAME name — `(role) WHERE role IN ('lawyer','admin')`. Because
--   the name was taken, IF NOT EXISTS made that a silent no-op and the partial
--   index was never created. Harmless (the plain index still serves the
--   queries) but the intent did not survive. To claim it:
--     DROP INDEX public.idx_profiles_role;
--     CREATE INDEX idx_profiles_role ON public.profiles(role) WHERE role IN ('lawyer','admin');


-- ############################################################################
-- ## 9/17  20261006_public_inquiry_rpc.sql
-- ############################################################################
-- ============================================================================
-- 20261006  Public inquiry submission
-- ============================================================================
-- The contact form, the consultation booking, and the seminar registration all
-- funnel through submitInquiry() in src/utils/api.ts. Until now that did a
-- direct INSERT and asked for the row back:
--
--   .insert({...}).select('*').single()
--
-- which cannot work for a signed-out visitor, in two separate ways:
--
--   1. inquiry_number has DEFAULT public.generate_inquiry_number(), and a
--      DEFAULT expression runs as the INSERTING role. schema-production.sql
--      grants the function and the sequence to authenticated only, so an
--      anonymous insert died at the DEFAULT with
--        42501 permission denied for sequence inquiry_number_seq
--      This is the live failure that was reported from the browser.
--
--   2. Even with the grant fixed, .select('*') asks PostgREST for
--      INSERT ... RETURNING *. inquiries_select_policy is TO authenticated, so
--      for anon the RETURNING clause yields no rows: the insert succeeds, the
--      response comes back empty, and .single() raises PGRST116. The visitor
--      sees an error for an inquiry that WAS created — the worst of both, since
--      they resubmit and the firm gets duplicates.
--
-- A SECURITY DEFINER function fixes both at once: it runs as its owner, so the
-- sequence is reachable and RETURNING can read the row it just wrote, and it
-- hands back only the reference number.
--
-- It also gives the public form a single validated entry point. The table
-- policies in 20261005 section 7 still stand for anything that writes directly;
-- this is the path the app uses.
--
-- Safe to re-run.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.submit_inquiry(
  p_name          TEXT DEFAULT NULL,
  p_email         TEXT DEFAULT NULL,
  p_phone         TEXT DEFAULT NULL,
  p_practice_area TEXT DEFAULT NULL,
  p_method        TEXT DEFAULT NULL,
  p_message       TEXT DEFAULT NULL,
  p_subject       TEXT DEFAULT NULL
) RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_number TEXT;
  v_uid    UUID := (SELECT auth.uid());
BEGIN
  -- Validated here rather than only in the browser: this function is reachable
  -- by anyone, so it cannot assume the form ran. ERRCODE 22023 is what makes
  -- PostgREST return 400 with this message instead of a generic failure.
  IF btrim(COALESCE(p_name, '')) = '' THEN
    RAISE EXCEPTION 'Please enter your name' USING ERRCODE = '22023';
  END IF;
  IF btrim(COALESCE(p_email, '')) = ''
     OR p_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RAISE EXCEPTION 'Please enter a valid email address' USING ERRCODE = '22023';
  END IF;
  IF btrim(COALESCE(p_message, '')) = '' THEN
    RAISE EXCEPTION 'Please tell us how we can help' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.inquiries (
    name, email, phone, practice_area, preferred_contact_method,
    message, subject, status, client_id
  ) VALUES (
    btrim(p_name),
    btrim(p_email),
    NULLIF(btrim(COALESCE(p_phone, '')), ''),
    COALESCE(btrim(COALESCE(p_practice_area, '')), ''),
    COALESCE(NULLIF(btrim(COALESCE(p_method, '')), ''), 'Email'),
    p_message,
    COALESCE(NULLIF(btrim(COALESCE(p_subject, '')), ''), 'General inquiry'),
    'New',
    -- The visitor cannot choose who this is filed under; it is themselves, or
    -- nobody when they are signed out. Same rule as inquiries_insert_policy.
    -- (client_id only — inquiries has no user_id column on live.)
    v_uid
  )
  RETURNING inquiry_number INTO v_number;

  RETURN v_number;
END $$;

REVOKE ALL ON FUNCTION public.submit_inquiry(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_inquiry(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT)
  TO anon, authenticated;


-- ----------------------------------------------------------------------------
-- Verify
-- ----------------------------------------------------------------------------
-- Deliberately read-only. An earlier draft round-tripped the function and then
-- deleted the probe row, which would have written to the firm's live inquiry
-- queue during a migration. The behaviour is proven in
-- scripts/local-pg-validate.sh instead, against a throwaway cluster.
DO $$
DECLARE v_sig TEXT := 'public.submit_inquiry(text,text,text,text,text,text,text)';
BEGIN
  IF to_regprocedure(v_sig) IS NULL THEN
    RAISE WARNING 'submit_inquiry was NOT created — the public contact form will fail';
  ELSIF NOT has_function_privilege('anon', v_sig, 'EXECUTE') THEN
    RAISE WARNING 'anon cannot execute submit_inquiry — the public contact form will fail';
  ELSIF NOT has_function_privilege('authenticated', v_sig, 'EXECUTE') THEN
    RAISE WARNING 'authenticated cannot execute submit_inquiry';
  ELSE
    RAISE NOTICE 'submit_inquiry is installed and callable by anon and authenticated';
  END IF;
END $$;


-- ############################################################################
-- ## 10/17  20261007_content_table_grants.sql
-- ############################################################################
-- ============================================================================
-- CONTENT TABLE GRANTS — the live "Admin access is required" failure
-- ============================================================================
-- Reported 2026-09-30: signed in as an admin, every write on Website Content
-- answered "You do not have permission to change this. Admin access is
-- required." That string comes from friendlyError(), which fires on both
-- "row-level security" and "permission denied". The live project answers
--
--   POST /rest/v1/articles  ->  42501 "permission denied for table articles"
--                               hint: GRANT INSERT ON public.articles TO anon
--
-- i.e. a GRANT-level denial, not an RLS one. The eight content tables were
-- created by 20260918, which is not part of the apply chain, and the project's
-- blanket default privileges did not cover them. §11 of 20261005 already fixed
-- this same class of gap for the four 20261001 tables; these are the rest.
--
-- Note what the local harness can and cannot see: it sets
-- ALTER DEFAULT PRIVILEGES, so every table IT creates is granted
-- automatically and this bug is invisible there. The end state is therefore
-- asserted the hard way in scripts/local-pg-validate.sh — revoke the grants,
-- re-apply THIS file alone, and require them back.
--
-- RLS is still the gate. anon may only read what the public select policies
-- allow, and every write policy on these tables still requires an active
-- admin (or the row's author, for articles). These grants only let the
-- policies run at all.

-- ----------------------------------------------------------------------------
-- 1. Table grants
-- ----------------------------------------------------------------------------
-- anon  : SELECT only — the public site reads published/active rows.
-- authed: full DML — the admin Content Manager writes; RLS filters the rest.
-- Guarded with to_regclass so a database where a table is absent (or was
-- renamed) still completes the paste instead of dying half way.
DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'practice_areas', 'articles', 'specialists', 'corporate_clients',
    'faqs', 'seminar_events', 'retainer_packages', 'profile_practice_areas'
  ] LOOP
    IF to_regclass('public.' || t) IS NOT NULL THEN
      EXECUTE format('GRANT SELECT ON public.%I TO anon', t);
      EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated, service_role', t);
    END IF;
  END LOOP;
END $$;

-- ----------------------------------------------------------------------------
-- 2. Re-assert the admin write policies
-- ----------------------------------------------------------------------------
-- Belt and braces for the other half of friendlyError(): if the failure was
-- RLS rather than the grant, it is because the policy is missing or stale on
-- the live project. DROP + CREATE makes the end state deterministic either
-- way, and switches the inline `role = 'admin'` subquery for the hardened
-- private.is_admin() helper that 20261003 installs (active, not deleted).
--
-- Only the write policies are touched. The public select policies are
-- demonstrably in force on the live project — anon reads the content tables
-- today — and rewriting them would change nothing.

DROP POLICY IF EXISTS practice_areas_admin_all ON public.practice_areas;
CREATE POLICY practice_areas_admin_all
ON public.practice_areas FOR ALL
TO authenticated
USING ((SELECT private.is_admin()))
